--
-- Name: fct_rmca_add_widgets_to_existing_users(character varying, character varying, character varying, integer, integer, boolean, boolean, boolean, character varying, boolean, integer, character varying, boolean); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_add_widgets_to_existing_users(p_cat character varying, p_group character varying, p_title character varying, p_order_by integer, p_col_num integer, p_mandatory boolean DEFAULT false, p_visible boolean DEFAULT true, p_opened boolean DEFAULT true, p_color character varying DEFAULT '#5BAABD'::character varying, p_available boolean DEFAULT true, p_icon_ref integer DEFAULT NULL::integer, p_collections character varying DEFAULT ','::character varying, p_all_public boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN

with a as (select user_ref from my_widgets where category=p_cat 
and group_name=p_group ),
b as (select users.* from users LEFT JOIN a
	 ON users.id=a.user_ref WHERE a.user_ref IS NULL
	 )
INSERT INTO darwin2.my_widgets(
	 user_ref,
	category, 
	group_name, 
	order_by, 
	col_num, 
	mandatory, 
	visible,
	opened, 
	color, 
	is_available, 
	icon_ref, 
	title_perso, 
	collections, 
	all_public)
	select b.id, p_cat, p_group, p_order_by::smallint,
	p_col_num::smallint, p_mandatory, p_visible, p_opened,
	p_color,
	p_available,
	p_icon_ref,
	p_title,
	p_collections,
	p_all_public from b;
	
	return true;
	
END;
$$;


