--
-- Name: staging_synonymies; Type: TABLE; Schema: darwin2; Owner: darwin2
--

CREATE TABLE darwin2.staging_synonymies (
    id integer NOT NULL,
    import_ref integer,
    taxo_valid_name character varying,
    taxo_valid_name_ref integer,
    valid_name character varying,
    valid_name_ref integer,
    valid_name_is_basionym boolean,
    taxo_syn character varying,
    taxo_syn_ref integer,
    syn_name character varying,
    syn_ref integer,
    status public.hstore DEFAULT ''::public.hstore NOT NULL,
    to_import boolean DEFAULT false,
    imported boolean DEFAULT false
);


ALTER TABLE darwin2.staging_synonymies OWNER TO darwin2;

--
-- Name: fct_rmca_imp_checker_manage_synonyms(darwin2.staging_synonymies); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_imp_checker_manage_synonyms(line darwin2.staging_synonymies) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
     result_nbr integer :=0;
	 rec_id_valid integer := null;
	 rec_id_syn integer := null;
	 ref_curs refcursor;
	 ref_record RECORD;
	 filter_taxonomy_str varchar;
	 go_valid boolean :=FALSE;
	 go_syn boolean :=FALSE;
	 txt_query varchar;
	 check_status varchar;
BEGIN
	IF COALESCE(line.imported,FALSE)=FALSE THEN
		UPDATE staging_synonymies SET status= ''::hstore WHERE staging_synonymies.id=line.id ;
	ELSE
		return TRUE;
	END IF;
    raise notice '---------';
    --valid name
	RAISE NOTICE 'valid';
	IF line.taxo_valid_name_ref IS NULL THEN
		filter_taxonomy_str:='';
	ELSE
		filter_taxonomy_str:=' metadata_ref='||line.taxo_valid_name_ref::varchar||' AND ';
	END IF;
	txt_query:= 'SELECT * from darwin2.taxonomy WHERE '||filter_taxonomy_str ||' name='||quote_literal(line.valid_name)|| ' LIMIT 2' ;
	RAISE notice '%', txt_query;
	OPEN ref_curs FOR EXECUTE txt_query;
	LOOP 
		FETCH ref_curs INTO ref_record;
		IF  NOT FOUND THEN
        	EXIT;  -- exit loop
      	END IF;
		rec_id_valid := ref_record.id;
      	result_nbr := result_nbr +1;		
    END LOOP;
	CLOSE ref_curs;
	IF result_nbr != 1 THEN
		txt_query:= 'SELECT * from darwin2.taxonomy
		WHERE '||filter_taxonomy_str ||' name_indexed=fulltoindex('||quote_literal(line.valid_name)|| ') LIMIT 2';
		RAISE notice '%', txt_query;
		OPEN ref_curs FOR EXECUTE txt_query ;
		LOOP 
			FETCH ref_curs INTO ref_record;
			IF  NOT FOUND THEN
				EXIT;  -- exit loop
			END IF;
			rec_id_valid := ref_record.id;
			result_nbr := result_nbr +1;
		END LOOP;
		CLOSE ref_curs;
	END IF;
	IF result_nbr = 1 THEN -- It's Ok!
		UPDATE staging_synonymies SET valid_name_ref=rec_id_valid WHERE staging_synonymies.id=line.id;
		go_valid:=TRUE;
	END IF;
	IF result_nbr >= 2 THEN
      UPDATE staging_synonymies SET status = (status || hstore('valid_name' , 'too_much')) where staging_synonymies.id= line.id;      
    END IF;
	IF result_nbr =0  THEN
      UPDATE staging_synonymies SET status = (status || hstore('valid_name' , 'not_found')) where staging_synonymies.id= line.id;      
    END IF;
	
	--syn
	RAISE NOTICE 'syn';
	result_nbr:=0;
	IF line.taxo_syn_ref IS NULL THEN
		filter_taxonomy_str:='';
	ELSE
		filter_taxonomy_str:=' metadata_ref='||line.taxo_valid_name_ref::varchar||' AND ';
	END IF;
	txt_query:= 'SELECT * from darwin2.taxonomy WHERE '||filter_taxonomy_str ||' name='||quote_literal(line.syn_name)|| ' LIMIT 2';
	RAISE notice '%', txt_query;
	OPEN ref_curs FOR EXECUTE txt_query;
	LOOP 
		FETCH ref_curs INTO ref_record;
		IF  NOT FOUND THEN
        	EXIT;  -- exit loop
      	END IF;
		rec_id_syn := ref_record.id;
      	result_nbr := result_nbr +1;
    END LOOP;
	CLOSE ref_curs;
	IF result_nbr != 1 THEN
		txt_query:= 'SELECT * from darwin2.taxonomy WHERE '||filter_taxonomy_str ||' name_indexed=fulltoindex('||quote_literal(line.syn_name)|| ') LIMIT 2' ;
		raise notice '%', txt_query;
		OPEN ref_curs FOR EXECUTE txt_query;
		LOOP 
			FETCH ref_curs INTO ref_record;
			IF  NOT FOUND THEN
				EXIT;  -- exit loop
			END IF;
			rec_id_syn := ref_record.id;
			result_nbr := result_nbr +1;
		END LOOP;
		CLOSE ref_curs;
	END IF;
	IF result_nbr = 1 THEN -- It's Ok!
		UPDATE staging_synonymies SET syn_ref=rec_id_syn WHERE staging_synonymies.id=line.id;
		go_syn:=TRUE;
	END IF;
	IF result_nbr >= 2 THEN
      UPDATE staging_synonymies SET status = (status || hstore('synonym' , 'too_much')) where staging_synonymies.id= line.id;      
    END IF;
	IF result_nbr =0  THEN
      UPDATE staging_synonymies SET status = (status || hstore('synonym' , 'not_found')) where staging_synonymies.id= line.id;      
    END IF;
	
	
	
	IF go_valid AND go_syn THEN
		SELECT * INTO line FROM staging_synonymies WHERE id=line.id;
		raise notice '%',rec_id_valid;
		raise notice '%',rec_id_syn;
		select cpt into result_nbr from darwin2.fct_rmca_taxon_check_synonymy_exists(rec_id_valid, rec_id_syn) as cpt;
		IF result_nbr =0 THEN
			UPDATE staging_synonymies SET to_import=TRUE where staging_synonymies.id= line.id;   
		ELSE
			 UPDATE staging_synonymies SET status = (status || hstore('synonym' , 'already_exists')) where staging_synonymies.id= line.id;  
		END IF;
		raise notice 'valid_name_ref in db %',line.valid_name_ref;
		check_status:= fct_rmca_taxonomy_create_synonym_check_status(line.valid_name_ref, line.syn_ref, 'taxonomy', line.valid_name_is_basionym, false, line.import_ref, FALSE );
		 raise notice 'check_status: %' , check_status;
		 UPDATE staging_synonymies SET status = (status || hstore('synonym' ,check_status )) where staging_synonymies.id= line.id;  
	END IF;
	raise notice '---end----';
  RETURN true;
END;
$$;


ALTER FUNCTION darwin2.fct_rmca_imp_checker_manage_synonyms(line darwin2.staging_synonymies) OWNER TO darwin2;

--
-- Name: fct_rmca_imp_checker_manage_synonyms_launch(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_imp_checker_manage_synonyms_launch(p_import_ref integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
	declare
		cpt int;
	begin
		perform darwin2.fct_rmca_imp_checker_manage_synonyms(staging_synonymies.*) FROM staging_synonymies where import_ref=p_import_ref;
		SELECt count(*) into cpt from staging_synonymies where import_ref=p_import_ref;
		IF cpt>0 then
			UPDATE imports set state='pending' where id=p_import_ref;
		END IF;
		return true;	
	end;
	$$;


ALTER FUNCTION darwin2.fct_rmca_imp_checker_manage_synonyms_launch(p_import_ref integer) OWNER TO darwin2;

--
-- Name: fct_rmca_imp_checker_specimen_code(darwin2.staging, integer, boolean); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_imp_checker_specimen_code(line darwin2.staging, collection_ref integer, import boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
	code_main varchar;
	returned BOOLEAN;

BEGIN
	

	SELECT full_code_indexed INTO code_main FROM codes WHERe referenced_relation='staging' and code_category='main' AND record_id=line.id;
raise notice 'test %', code_main;
	IF code_main IS NOT NULL THEN
	raise notice 'go';
		returned:= fct_rmca_collection_check_code_unicity(collection_ref, code_main)  ;
		If returned THEN
			raise notice 'set false';
			UPDATE staging SET status = (status || hstore('code' , 'too_much')) where staging.id= line.id; 
			RETURN FALSE;
		END IF;
	END IF;
  

  RETURN true;
END;
$$;


ALTER FUNCTION darwin2.fct_rmca_imp_checker_specimen_code(line darwin2.staging, collection_ref integer, import boolean) OWNER TO darwin2;

