    specimen_ref integer,
    code_category character varying DEFAULT 'main'::character varying NOT NULL,
    code_prefix character varying,
    code_prefix_separator character varying,
    code character varying,
    code_suffix character varying,
    code_suffix_separator character varying,
    status public.hstore DEFAULT ''::public.hstore NOT NULL,
    to_import boolean DEFAULT false,
    imported boolean DEFAULT false
);


ALTER TABLE darwin2.staging_codes OWNER TO darwin2;

--
-- Name: fct_rmca_imp_manager_create_code(darwin2.staging_codes); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_imp_manager_create_code(line darwin2.staging_codes) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE returned boolean;
DECLARE replace_old boolean;
BEGIN
	returned:=false;
	IF line.specimen_ref IS NOT NULL AND COALESCE(line.imported,FALSE)=FALSE THEN
		SELECT COALESCE(update, FALSE) INTO replace_old FROM darwin2.imports WHERE imports.id=line.import_ref;
		IF replace_old THEN
			DELETE FROM darwin2.codes WHERE 
				referenced_relation='specimens' 
				AND record_id=line.specimen_ref
				AND LOWER(code_category)=LOWER(line.code_category)
				;
		END IF;
		INSERT INTO codes (referenced_relation, record_id,  code_category, code_prefix, code_prefix_separator, code, code_suffix, code_suffix_separator,     import_ref) 
		VALUES 
		('specimens', line.specimen_ref,  line.code_category, line.code_prefix,  
		line.code_prefix_separator, line.code, line.code_suffix, line.code_suffix_separator, 
		  line.import_ref)
		;
	
		UPDATE staging_codes SET imported=true , status=  hstore('specimen' , 'ok')
			WHERE staging_codes.id=line.id;
			return true;
		
	END IF;
	RETURN returned;
END
$$;


ALTER FUNCTION darwin2.fct_rmca_imp_manager_create_code(line darwin2.staging_codes) OWNER TO darwin2;

