--
-- Name: fct_rmca_imp_manager_create_property(darwin2.staging_properties); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_imp_manager_create_property(line darwin2.staging_properties) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE returned boolean;
DECLARE replace_old boolean;
BEGIN
	returned:=false;
	IF line.specimen_ref IS NOT NULL AND COALESCE(line.imported,FALSE)=FALSE THEN
		SELECT COALESCE(update, FALSE) INTO replace_old FROM darwin2.imports WHERE imports.id=line.import_ref;
		IF replace_old THEN
			DELETE FROM darwin2.properties WHERE 
				referenced_relation='specimens' 
				AND record_id=line.specimen_ref
				AND property_type=line.property_type
				AND COALESCE(applies_to,'')=COALESCE(line.applies_to,'');
		END IF;
		INSERT INTO properties (referenced_relation, record_id,  property_type, applies_to,  
		date_from_mask, date_from, date_to_mask, date_to, is_quantitative, property_unit, method, 
		 lower_value,  upper_value,  
		property_accuracy,  import_ref) 
		VALUES 
		('specimens', line.specimen_ref,  line.property_type, line.applies_to,  
		line.date_from_mask, line.date_from, line.date_to_mask, line.date_to, 
		line.is_quantitative, line.property_unit, line.method, 
		 line.lower_value,  line.upper_value,  
		line.property_accuracy,  line.import_ref)
		;
	
		UPDATE staging_properties SET imported=true , status=  hstore('specimen' , 'ok')
			WHERE staging_properties.id=line.id;
			return true;
		
	END IF;
	RETURN returned;
END
$$;


