--

CREATE FUNCTION darwin2.fct_rmca_imp_manager_create_relationship(line darwin2.staging_update_specimen_relationship) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE returned boolean;
DECLARE replace_old boolean;
BEGIN
	returned:=false;
	IF line.specimen_ref IS NOT NULL AND line.specimen_related_ref IS NOT NULL AND COALESCE(line.imported,FALSE)=FALSE
	THEN
		
		INSERT INTO specimens_relationships
		(specimen_ref, relationship_type, unit_type, specimen_related_ref, import_ref) 
		VALUES 
		(line.specimen_ref, line.relationship_type, 'specimens', line.specimen_related_ref, line.import_ref)
		;
	
		UPDATE staging_update_specimen_relationship
		SET imported=true , status=  (hstore('specimen' , 'ok')||hstore('related_specimen' , 'ok'))::hstore
			WHERE staging_update_specimen_relationship.id=line.id;
			return true;
		
	END IF;
	RETURN returned;
END
