--
-- Name: fct_rmca_import_check_codes_launch(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_import_check_codes_launch(p_import_ref integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
	returned boolean;
	--curs CURSOR FOR SELECT fct_rmca_import_check_properties_status() FROM staging_properties WHERE import_ref=p_import_ref;
	  rec record;
	  spec_id integer;
BEGIN
	returned:=false;
	
	FOR rec IN SELECT id, fct_rmca_import_check_properties_status(specimen_main_id, specimen_uuid::varchar) as 
	rep, specimen_main_id, specimen_uuid FROM staging_codes WHERE import_ref=p_import_ref and coalesce(imported, FALSE)=FALSE
	LOOP
		IF rec.rep = 'ok' THEN
			spec_id:=fct_rmca_import_check_properties(rec.specimen_main_id, rec.specimen_uuid::varchar);
			UPDATE staging_codes SET status=  hstore('specimen' , 'ok'), specimen_ref=spec_id WHERE id=rec.id;
			returned:=true;
		ELSE
			UPDATE staging_codes SET status  =  hstore('specimen' , rec.rep)  WHERE id=rec.id;
		
		END IF;
	END LOOP;
	
	
	
	return returned;
END;
$$;


ALTER FUNCTION darwin2.fct_rmca_import_check_codes_launch(p_import_ref integer) OWNER TO darwin2;

--
-- Name: fct_rmca_import_check_properties(character varying, character varying); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_import_check_properties(p_code character varying, p_uuid character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	spec_id integer;
	cpt bigint;
BEGIN
	spec_id:=NULL;
	IF p_uuid IS NOT NULL THEN
		SELECT id,  count(*) over (partition by null) into spec_id, cpt FROM specimens 
		where uuid::varchar=p_uuid LIMIT 1;
		IF spec_id IS NOT NULL and cpt=1 THEN
			RETURN spec_id;
		END IF;
	ELSE
		select record_id,  count(*) over (partition by null) INTO spec_id, cpt FROM codes 
		WHERE referenced_relation='specimens' 
		and LOWER(code_category)='main' and full_code_indexed=fulltoindex(p_code,FALSE) LIMIT 1;
		IF spec_id IS NOT NULL and cpt=1 THEN
			RETURN spec_id;
		END IF;
	END IF;
	RETURN spec_id;
END
$$;


ALTER FUNCTION darwin2.fct_rmca_import_check_properties(p_code character varying, p_uuid character varying) OWNER TO darwin2;

