--
-- Name: fct_rmca_import_check_properties_status(character varying, character varying); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_import_check_properties_status(p_code character varying, p_uuid character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	returned varchar;
	cpt bigint;
BEGIN
	returned:=NULL;
	IF p_uuid IS NOT NULL THEN
		SELECT   count(*) over (partition by null) into  cpt FROM specimens where uuid::varchar=p_uuid LIMIT 1;
		cpt:=COALESCE(cpt,0);
		IF cpt =0 THEN
			RETURN 'not_found';
		ELSEIF cpt =1 THEN
			RETURN 'ok';
		ELSEIF cpt >1 THEN
			RETURN 'too_many_data';
		END IF;
	ELSE
		select   count(*) over (partition by null) INTO  cpt FROM codes WHERE referenced_relation='specimens' 
		and LOWER(code_category)='main' and full_code_indexed=fulltoindex(p_code,false) LIMIT 1;
		cpt:=COALESCE(cpt,0);
		IF cpt =0 THEN
			RETURN 'not_found';
		ELSEIF cpt =1 THEN
			RETURN 'ok';
		ELSEIF cpt >1 THEN
			RETURN 'too_many_data';
		END IF;
	END IF;
	RETURN returned;
END
$$;


ALTER FUNCTION darwin2.fct_rmca_import_check_properties_status(p_code character varying, p_uuid character varying) OWNER TO darwin2;

--
-- Name: fct_rmca_import_check_relationship_status_split(integer, character varying, character varying); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_import_check_relationship_status_split(p_submitted_ref integer, p_code character varying, p_uuid character varying) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	returned varchar;
	cpt bigint;
BEGIN
	--RAISE NOTICE 'darwin2.fct_rmca_import_check_relationship_status_split called';
	returned:=NULL;
	IF p_submitted_ref IS NOT NULL THEN
	    --RAISE NOTICE 'p_submitted_ref NOT NULL';
		SELECT   count(*) over (partition by null) into  cpt FROM specimens where id=p_submitted_ref LIMIT 1;
		cpt:=COALESCE(cpt,0);
		IF cpt =0 THEN
			RETURN 'not_found';
		ELSEIF cpt =1 THEN
			RETURN 'ok';
		ELSEIF cpt >1 THEN
			RETURN 'too_many_data';
		END IF;
	ELSEIF p_uuid IS NOT NULL THEN
		--RAISE NOTICE 'p_uuid NOT NULL';
		SELECT   count(*) over (partition by null) into  cpt FROM specimens where uuid::varchar=p_uuid LIMIT 1;
		cpt:=COALESCE(cpt,0);
		IF cpt =0 THEN
			RETURN 'not_found';
		ELSEIF cpt =1 THEN
			RETURN 'ok';
		ELSEIF cpt >1 THEN
			RETURN 'too_many_data';
		END IF;
	ELSE
		--RAISE NOTICE 'p_code NOT NULL';
		--RAISE NOTICE '%', fulltoindex(p_code,false);
		select   count(*) over (partition by null) INTO  cpt FROM codes WHERE referenced_relation='specimens' 
		and LOWER(code_category)='main' and full_code_indexed=fulltoindex(p_code,false) LIMIT 1;
		cpt:=COALESCE(cpt,0);
		IF cpt =0 THEN
		    --RAISE NOTICE 'p_code not found';
			RETURN 'not_found';
		ELSEIF cpt =1 THEN
			--RAISE NOTICE 'p_code  found';
			RETURN 'ok';
		ELSEIF cpt >1 THEN
		    --RAISE NOTICE 'too many p_code';
			RETURN 'too_many_data';
		END IF;
	END IF;
	RETURN returned;
END
$$;


ALTER FUNCTION darwin2.fct_rmca_import_check_relationship_status_split(p_submitted_ref integer, p_code character varying, p_uuid character varying) OWNER TO darwin2;

--
-- Name: fct_rmca_import_check_relationships_launch(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_import_check_relationships_launch(p_import_ref integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
	returned boolean;
	
	  rec record;
	  spec_id integer;
	  related_spec_id integer;
BEGIN
	returned:=false;
	
	FOR rec IN SELECT id, fct_rmca_import_check_relationship_status_split(
		specimen_submitted_ref, specimen_main_code, specimen_uuid::varchar
		
	) 
	as rep1,
	fct_rmca_import_check_relationship_status_split(
		specimen_related_submitted_ref, specimen_related_main_code, specimen_related_uuid::varchar
	) 
	as rep2,
	specimen_submitted_ref, specimen_main_code, specimen_uuid,
		specimen_related_submitted_ref, specimen_related_main_code, specimen_related_uuid
		FROM staging_update_specimen_relationship 
	WHERE import_ref=p_import_ref and coalesce(imported, FALSE)=FALSE
	LOOP
		IF rec.rep1 = 'ok' AND rec.rep2='ok' THEN
			IF rec.specimen_submitted_ref IS NOT NULL THEN 
				spec_id:=rec.specimen_submitted_ref;
			ELSE
				spec_id:=fct_rmca_import_check_properties(rec.specimen_main_code, rec.specimen_uuid::varchar);
			END IF;
			IF rec.specimen_related_submitted_ref IS NOT NULL THEN 
				related_spec_id:=rec.specimen_related_submitted_ref;
			ELSE
				related_spec_id:=fct_rmca_import_check_properties(rec.specimen_related_main_code, 
																  rec.specimen_related_uuid::varchar);
			END IF;
			UPDATE staging_update_specimen_relationship SET status=  (hstore('specimen' , 'ok')|| hstore('related_specimen' , 'ok'))::hstore, 
				specimen_ref=spec_id ,
				specimen_related_ref=related_spec_id 
				WHERE id=rec.id;
			returned:=true;
		ELSE
		    --RAISE NOTICE '%',rec.rep1;
			--RAISE NOTICE '%',rec.rep2;
			UPDATE staging_update_specimen_relationship SET status  =  hstore('specimen ' , rec.rep1)  WHERE id=rec.id;
			UPDATE staging_update_specimen_relationship SET status  = (status|| hstore('related_specimen' , rec.rep2))::hstore  WHERE id=rec.id;
		
		END IF;
	END LOOP;
	
	
	
	return returned;
END;
$$;


ALTER FUNCTION darwin2.fct_rmca_import_check_relationships_launch(p_import_ref integer) OWNER TO darwin2;

--
-- Name: fct_rmca_instit_address_from_loan_actor(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_instit_address_from_loan_actor(id integer) RETURNS TABLE(id_instit text, instit text, entry text, zip text, locality text, address text, country text)
    LANGUAGE sql
    AS $_$

SELECT 
  (p.formated_name || '§§§' || pr.person_1_ref) AS Id_instit, p.formated_name, COALESCE(a.entry::text),COALESCE(a.zip_code::text), COALESCE(a.locality::text), COALESCE(a.entry::text) || ' ' ||  COALESCE(a.zip_code::text) || ' ' || COALESCE(a.locality::text)  AS address,  COALESCE(a.country::text)
FROM 
  people_relationships pr
LEFT JOIN people p
	ON p.id = pr.person_1_ref
LEFT JOIN people_addresses a
	ON pr.person_1_ref = a.person_user_ref
WHERE 
  pr.person_2_ref = $1 AND
  (pr.relationship_type = 'works for' OR 
  pr.relationship_type = 'belongs to')
  
$_$;


ALTER FUNCTION darwin2.fct_rmca_instit_address_from_loan_actor(id integer) OWNER TO darwin2;

--
-- Name: fct_rmca_keep_staging_catalogue_parent(); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_keep_staging_catalogue_parent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP ='INSERT' THEN
    NEW.parent_ref_internal=NEW.parent_ref;
  
  ELSIF TG_OP ='UPDATE' AND NEW.parent_updated=FALSE  THEN
    NEW.parent_ref_internal=NEW.parent_ref;  
    
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION darwin2.fct_rmca_keep_staging_catalogue_parent() OWNER TO darwin2;

--
-- Name: fct_rmca_log_original_specimens_id_uuid(); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_log_original_specimens_id_uuid() RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN 
       
        with updated AS
        (
	SELECT DISTINCT
		old_value->'id' old_id, new_value->'id' new_id,  specimen_ref
		FROM 
		(select new_value, old_value from users_tracking where referenced_relation='specimens' and action='update' --AND new_value->'id'!=old_value->'id'
		 ) a
		LEFT JOIN specimens on  (new_value->'id')::int=specimens.id
		LEFT JOIN specimens_stable_ids ON  (old_value->'id')::int=original_id 
		WHERE (old_value->'id'  <>  new_value->'id') 
				
	)
	UPDATE specimens_stable_ids SET specimen_ref=new_id::bigint FROM updated WHERE original_id=old_id::bigint;


	 with old_inserted AS
        (
	SELECT 
		 new_value->'id' new_id,  specimen_ref
		FROM 
		(select new_value, old_value from users_tracking where referenced_relation='specimens' and ( action='update' OR action='insert')
		 ) a
		LEFT JOIN specimens on  (new_value->'id')::int=specimens.id
		LEFT JOIN specimens_stable_ids ON  (new_value->'id')::int=original_id 
		WHERE  specimens.id IS NULL AND original_id IS NULL
				
	)
	INSERT INTO specimens_stable_ids (specimen_ref) SELECT DISTINCT new_id::bigint FROM old_inserted;

	/*WITH non_logged_uuid
	AS
	(
		SELECT DISTINCT specimens.id, specimens.uuid FROM specimens INNER JOIN
		specimens_stable_ids ON specimens.id=specimen_ref WHERE specimens_stable_ids.uuid IS NULL
	)
	UPDATE specimens_stable_ids SET uuid=non_logged_uuid.uuid FROM non_logged_uuid WHERE non_logged_uuid.id=specimen_ref ;
	*/

	WITH new_specimens
	AS
	(
		SELECT DISTINCT specimens.id FROM specimens LEFT JOIN
		specimens_stable_ids ON specimens.id=specimen_ref WHERE specimen_ref IS NULL
	)
	INSERT INTO specimens_stable_ids (specimen_ref, specimen_fk) SELECT DISTINCT id, id FROM new_specimens;
	RETURN true;

END

$$;


ALTER FUNCTION darwin2.fct_rmca_log_original_specimens_id_uuid() OWNER TO darwin2;

--
-- Name: fct_rmca_look_related_specimens(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_look_related_specimens(p_specimen_ref integer) RETURNS TABLE(id integer)
    LANGUAGE plpgsql
    AS $$
declare

current_Ref integer;
counter integer;
counter_2 integer;

int_list integer[];
i integer;
begin
	i=0;
	
	counter:=-1;
	counter_2:=0;
	current_ref=p_specimen_ref;
	DROP   table if  exists tmp_list_related;
	DROP   table if  exists tmp_list_related;
	 CREATE  temporary table if not exists tmp_list_related(id integer );
	 CREATE  temporary table if not exists tmp_list_related_2(id integer );
	 insert into tmp_list_related_2 VALUES(p_specimen_ref);
	WHILE (counter_2!=counter AND i<200)
	LOOP
		counter:=counter_2;
		 INSERT INTO tmp_list_related(id)  SELECT DISTINCT tmp_id FROM (select specimen_ref as tmp_id FROM specimens_relationships 

		 INNER JOIN  tmp_list_related_2 ON specimen_related_ref=tmp_list_related_2.id
		union 
		select specimen_related_ref FROM specimens_relationships 
		INNER JOIN  tmp_list_related_2 ON specimen_ref=tmp_list_related_2.id
		) a WHERE tmp_id NOT IN (SELECT tmp_list_related.id FROM tmp_list_related ) ;
		i:=i+1;
		INSERT INTO tmp_list_related SELECT * FROM tmp_list_related_2;
		DELETE FROM tmp_list_related_2;
		SELECT COUNT(DISTINCT tmp_list_related.id) into counter_2 FROM tmp_list_related;
	END LOOP;
	
	--DROP TABLE tmp_list_related;
