--
-- Name: fct_rmca_specimens_relationships_lateral(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_specimens_relationships_lateral(integer) RETURNS TABLE(rel_path integer[], direction_path text[], type_path character varying[], src_specimen_ref integer, level integer, direction text, id integer, specimen_ref integer, relationship_type character varying, spec_taxon_ref integer, taxon_name character varying, related_specimen_uuid uuid)
    LANGUAGE sql
    AS $_$
with b
AS 
	(
	select ARRAY[specimen_ref]::int[] as rel_path, 
	ARRAY[direction]::text[]   as direction_path,
 ARRAY[relationship_type]::varchar[]   as type_path,
 1 as level,
 specimen_ref src_specimen_ref,
	v_specimens_relationships_bi_directional.id,
	v_specimens_relationships_bi_directional.direction,
	v_specimens_relationships_bi_directional.specimen_ref,
	v_specimens_relationships_bi_directional.specimen_related_ref,
	v_specimens_relationships_bi_directional.relationship_type
	from
	v_specimens_relationships_bi_directional WHERE  specimen_ref=$1)
	, c as (
	select distinct 
	COALESCE(c_b.rel_path , b.rel_path) rel_path ,
	COALESCE(c_b.direction_path , b.direction_path) direction_path ,
	COALESCE(c_b.type_path , b.type_path) type_path ,
	coalesce(c_b.direction, b.direction) as direction ,
	coalesce(c_b.level, b.level) as level ,
	src_specimen_ref,
	b.specimen_ref b_specimen_ref, 
	b.specimen_related_ref  b_specimen_related_ref,
    b.relationship_type b_relationship_type,
	b.specimen_ref, 
	COALESCE(c_b.specimen_related_ref, b.specimen_related_ref) specimen_related_ref ,
	COALESCE(c_b.relationship_type, b.relationship_type) relationship_type
	from b
	LEFT JOIN LATERAL (SELECT 
	b.rel_path||c.specimen_ref as rel_path ,
	b.direction_path||c.direction as direction_path,
	b.type_path||c.relationship_type as type_path,
	
	b.level+1 as level,
	*
	FROM v_specimens_relationships_bi_directional c
	WHERE b.specimen_related_ref=c.specimen_Ref
	and not c.specimen_related_Ref = ANY (rel_path)
	) as c_b on true)
	, d as (
	select 
	rel_path,
	direction_path,
	type_path,
	direction,
	level,
	src_specimen_ref,
	specimen_ref, 
	specimen_related_ref ,
	relationship_type from c
	union 
	select rel_path,
	direction_path,
	type_path,
	direction,
	level,
	src_specimen_ref,
	b_specimen_ref, 
	b_specimen_related_ref ,
	b_relationship_type from c
	union
	select 
	rel_path,
	direction_path,
	type_path,
	direction,
	level,
	src_specimen_ref,
	b.specimen_ref, 
	b.specimen_related_ref ,
	b.relationship_type from b
	
	)
	select distinct 
	rel_path,
	direction_path,
	type_path,	
	src_specimen_ref,
	level,
	direction,
	
	specimen_Ref,
	specimen_related_ref , 
	relationship_type,
	taxon_ref spec_taxon_ref,
	taxon_name,
	uuid related_specimen_uuid
	from d
	LEFT JOIN specimens
	ON 
	specimen_related_ref=specimens.id

	; 

$_$;


ALTER FUNCTION darwin2.fct_rmca_specimens_relationships_lateral(integer) OWNER TO darwin2;

--
-- Name: fct_rmca_specimens_relationships_recursive(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_specimens_relationships_recursive(integer) RETURNS TABLE(rel_path integer[], direction_path text[], type_path character varying[], src_specimen_ref integer, level integer, direction text, id integer, specimen_ref integer, relationship_type character varying, unit_type character varying, specimen_related_ref integer, taxon_ref integer, mineral_ref integer, institution_ref integer, source_name text, source_id text, quantity numeric, unit character varying, spec_taxon_ref integer, taxon_name character varying, related_specimen_uuid uuid, pdepth integer)
    LANGUAGE sql
    AS $_$
with recursive b as 
(
SELECT ARRAY[specimen_ref]::integer[]   as rel_path, 
 ARRAY[direction]::text[]   as direction_path,
 ARRAY[relationship_type]::varchar[]   as type_path,

specimen_ref as src_specimen_ref, 1 as level,
alias_b.*
,
specimens.taxon_ref, taxon_name, specimens.uuid, 1 as p_depth
FROM 

(
SELECT 'forward'::text AS direction,
    specimens_relationships.id,
    specimens_relationships.specimen_ref,
    specimens_relationships.relationship_type,
    specimens_relationships.unit_type,
    specimens_relationships.specimen_related_ref,
    specimens_relationships.taxon_ref,
    specimens_relationships.mineral_ref,
    specimens_relationships.institution_ref,
    specimens_relationships.source_name,
    specimens_relationships.source_id,
    specimens_relationships.quantity,
    specimens_relationships.unit
   FROM specimens_relationships
   WHERE specimen_ref= $1
UNION
 SELECT 'reverse'::text AS direction,
    specimens_relationships.id,
    specimens_relationships.specimen_related_ref AS specimen_ref,
    specimens_relationships.relationship_type,
    specimens_relationships.unit_type,
    specimens_relationships.specimen_ref AS specimen_related_ref,
    specimens_relationships.taxon_ref,
    specimens_relationships.mineral_ref,
    specimens_relationships.institution_ref,
    specimens_relationships.source_name,
    specimens_relationships.source_id,
    specimens_relationships.quantity,
    specimens_relationships.unit
   FROM specimens_relationships
   WHERE specimen_related_ref=  $1)
alias_b 
LEFT JOIN specimens ON specimen_related_ref=specimens.id

UNION 
SELECT rel_path||b2.specimen_ref, 
 
direction_path||b2.direction,
type_path||b2.relationship_type,
src_specimen_ref, level+1, b2.direction, b2.id,  b2.specimen_ref,
b2.relationship_type, b2.unit_type, b2.specimen_related_ref,
b2.taxon_ref, b2.mineral_ref, b2.institution_ref,b2.source_name, 
b2.source_id, b2.quantity, b2.unit 

,
specimens.taxon_ref as spec_taxon_ref, specimens.taxon_name , specimens.uuid, p_depth+1
FROM b 
LEFT JOIN
lateral 
(
SELECT 'forward'::text AS direction,
    specimens_relationships.id,
    specimens_relationships.specimen_ref,
    specimens_relationships.relationship_type,
    specimens_relationships.unit_type,
    specimens_relationships.specimen_related_ref,
    specimens_relationships.taxon_ref,
    specimens_relationships.mineral_ref,
    specimens_relationships.institution_ref,
    specimens_relationships.source_name,
    specimens_relationships.source_id,
    specimens_relationships.quantity,
    specimens_relationships.unit
   FROM specimens_relationships
   where  b.specimen_related_ref=specimens_relationships.specimen_ref
UNION
 SELECT 'reverse'::text AS direction,
    specimens_relationships.id,
    specimens_relationships.specimen_related_ref AS specimen_ref,
    specimens_relationships.relationship_type,
    specimens_relationships.unit_type,
    specimens_relationships.specimen_ref AS specimen_related_ref,
    specimens_relationships.taxon_ref,
    specimens_relationships.mineral_ref,
    specimens_relationships.institution_ref,
    specimens_relationships.source_name,
    specimens_relationships.source_id,
    specimens_relationships.quantity,
    specimens_relationships.unit
   FROM specimens_relationships
   where  b.specimen_related_ref=specimens_relationships.specimen_related_ref)
b2 ON true

LEFT JOIN specimens ON b2.specimen_related_ref=specimens.id
where NOT (b2.specimen_ref = ANY (rel_path))
and not
(b2.specimen_related_ref = ANY (rel_path))
AND p_depth<=4
)
select  * from b ;
$_$;


ALTER FUNCTION darwin2.fct_rmca_specimens_relationships_recursive(integer) OWNER TO darwin2;

--
-- Name: fct_rmca_specimens_relationships_recursive2(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_specimens_relationships_recursive2(integer) RETURNS TABLE(rel_path integer[], direction_path text[], type_path character varying[], src_specimen_ref integer, level integer, direction text, id integer, specimen_ref integer, relationship_type character varying, unit_type character varying, specimen_related_ref integer, taxon_ref integer, mineral_ref integer, institution_ref integer, source_name text, source_id text, quantity numeric, unit character varying, spec_taxon_ref integer, taxon_name character varying, related_specimen_uuid uuid)
    LANGUAGE sql
    AS $_$
with recursive b as 
(
SELECT ARRAY[specimen_ref]::integer[]   as rel_path, 
 ARRAY[direction]::text[]   as direction_path,
 ARRAY[relationship_type]::varchar[]   as type_path,

specimen_ref as src_specimen_ref, 1 as level,
v_specimens_relationships_bi_directional.*
,
specimens.taxon_ref, taxon_name, specimens.uuid
FROM v_specimens_relationships_bi_directional 
LEFT JOIN specimens ON specimen_related_ref=specimens.id
WHERE specimen_ref= $1
UNION 
SELECT rel_path||b2.specimen_ref, 
 
direction_path||b2.direction,
type_path||b2.relationship_type,
src_specimen_ref, level+1, b2.direction, b2.id,  b2.specimen_ref,
b2.relationship_type, b2.unit_type, b2.specimen_related_ref,
b2.taxon_ref, b2.mineral_ref, b2.institution_ref,b2.source_name, 
b2.source_id, b2.quantity, b2.unit 

,
specimens.taxon_ref as spec_taxon_ref, specimens.taxon_name , specimens.uuid
FROM b 

join
v_specimens_relationships_bi_directional b2
on  b.specimen_related_ref=b2.specimen_ref
LEFT JOIN specimens ON b2.specimen_related_ref=specimens.id
where NOT (b2.specimen_ref = ANY (rel_path))
and not
(b2.specimen_related_ref = ANY (rel_path))

)
select  * from b ;

$_$;


