    LANGUAGE sql
    AS $_$
with RECURSIVE a  as 
(
select id   from fct_rmca_taxo_get_syno_outer($1) tax
union 
select record_id FROM  a, fct_rmca_taxo_get_syno_direct_children_outer(a.id) a0 --inner join a oN taxonomy.parent_Ref=a.id
)
select distinct * from a
$_$;


