--
-- Name: fct_rmca_taxon_check_synonymy_exists(integer, integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxon_check_synonymy_exists(name1 integer, name2 integer) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	cpt int;
BEGIN
	raise notice '%', name1;
	raise notice '%', name2;
	WITH a as (
		select group_id, array_agg(record_id) list_taxa
		FROM darwin2.classification_synonymies
		where referenced_relation='taxonomy'

		GROUP BY group_id
	)
	
	SELECT COUNT(DISTINCT group_id) INTO cpt from a where list_taxa @> ARRAY[name1,name2 ];
	RETURN cpt;
END
$$;


