--
-- Name: fct_rmca_taxon_to_catalogolife_api(character varying, character varying, character varying); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxon_to_catalogolife_api(taxon character varying, url_prefix character varying DEFAULT 'http://api.checklistbank.org/dataset/'::character varying, dataset_key character varying DEFAULT '3LR'::character varying) RETURNS TABLE(url_col character varying, count_col integer, current_col integer, col_usage_key character varying, col_status character varying, col_rank character varying, col_scientific_name character varying, col_authorship character varying, col_link character varying, col_hierarchy_names character varying, col_hierarchy_ranks character varying, json_col character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE 
tmp record;
url_col2 varchar;
BEGIN
url_col2:=url_prefix||dataset_key||'/nameusage/search?q='||
		replace(taxon, ' ','%20');
		--raise notice '%', url_col2;
FOR tmp in 
	WITH a as (
	SELECT fct_rmca_py_webservice as json_col_tmp FROM   
		fct_rmca_py_webservice(
		url_col2) ) ,
		b as (select *, a.json_col_tmp::json->'total' as total
			  
			  ,json_array_elements(json_col_tmp::json->'result') as item
			  FROM a),
		c as(
		select
			
		
			(json_array_elements(item::json->'classification')->'rank')::varchar parent_rank,
(json_array_elements(item::json->'classification')->'name')::varchar parent_name,*
		 FROM b),
		 d as (
		 SELECT distinct
			 url_col2 tmp_url_col2,
			 (c.total)::text::int as tmp_count_col ,
			 string_agg(trim('"' from parent_rank), '/') as parent_ranks, 
			 string_agg(trim('"' from parent_name), '/') as parent_names,
			  trim('"' from (c.item->'usage'->'id')::varchar) tmp_col_usage_key,
			 trim('"' from (c.item->'usage'->'name'->'scientificName')::varchar) tmp_col_scientific_name,
		 trim('"' from (c.item->'usage'->'name'->'authorship')::varchar) tmp_col_authorship,
			 trim('"' from (c.item->'usage'->'name'->'link')::varchar) as tmp_col_link,
			 trim('"' from (c.item->'usage'->'status')::varchar) as tmp_col_status,
			 trim('"' from (c.item->'usage'->'name'->'rank')::varchar) as tmp_col_rank,
			  trim('"' from c.json_col_tmp::varchar) as json_col_tmp
			 from c 
		 	GROUP BY 
			 url_col2,
			 (c.total)::text::int,
			 trim('"' from (c.item->'usage'->'id')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'scientificName')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'authorship')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'link')::varchar),
			 trim('"' from (c.item->'usage'->'status')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'rank')::varchar),
				    trim('"' from c.json_col_tmp::varchar)
		 ) 
		 select 
		  *,  row_number() OVER () as rank_nb FROM d
		 LOOP
		   url_col:=tmp.tmp_url_col2;
		   count_col=tmp.tmp_count_col;
		   current_col:=tmp.rank_nb;
		   json_col:=tmp.json_col_tmp;
		   col_usage_key= tmp.tmp_col_usage_key;
		   col_scientific_name=tmp.tmp_col_scientific_name;
		   col_authorship=tmp.tmp_col_authorship;
		   col_link=tmp.tmp_col_link;
		   col_status= tmp.tmp_col_status;
		   col_rank=tmp.tmp_col_rank;
		   col_hierarchy_names:=tmp.parent_names;
		   col_hierarchy_ranks:=tmp.parent_ranks;
		return next;
		END LOOP;
END
$$;


ALTER FUNCTION darwin2.fct_rmca_taxon_to_catalogolife_api(taxon character varying, url_prefix character varying, dataset_key character varying) OWNER TO darwin2;

--
-- Name: fct_rmca_taxon_to_catalogolife_api_rank(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxon_to_catalogolife_api_rank(taxon character varying, tax_rank character varying, url_prefix character varying DEFAULT 'http://api.checklistbank.org/dataset/'::character varying, dataset_key character varying DEFAULT '3LR'::character varying) RETURNS TABLE(url_col character varying, count_col integer, current_col integer, col_usage_key character varying, col_status character varying, col_rank character varying, col_scientific_name character varying, col_authorship character varying, col_link character varying, col_hierarchy_names character varying, col_hierarchy_ranks character varying, json_col character varying)
    LANGUAGE plpgsql
    AS $$
DECLARE 
tmp record;
url_col2 varchar;
min_rank varchar;
max_rank varchar;
appendix varchar;
BEGIN
appendix='';
tax_rank:=LOWER(tax_rank);
IF tax_rank LiKE '%kingdom%' THEN
	appendix='&maxRank=SUPERPHYLUM&minRank=INFRAKINGDOM';
ELSEIF tax_rank LiKE '%phylum%' THEN
	appendix='&maxRank=SUPERKINGDOM&minRank=NANOPHYLUM';
ELSEIF tax_rank LiKE '%family%' THEN
	appendix='&maxRank=MEGAFAMILY&minRank=INFRAFAMILY';
ELSEIF tax_rank LiKE '%order%' THEN
	appendix='&maxRank=GIGAORDER&minRank=INFRAORDER';
ELSEIF tax_rank LiKE '%class%' THEN
	appendix='&maxRank=GIGACLASS&minRank=PARVCLASS';
ELSEIF tax_rank LiKE '%genus%' THEN
	appendix='&maxRank=SUPRAGENERIC_NAME&minRank=INFRAGENUS';
ELSEIF tax_rank ='species' THEN
	appendix='&maxRank=SPECIES&minRank=SPECIES';
ELSEIF tax_rank LIKE 'sub%species' THEN
	appendix='&maxRank=SUBSPECIES&minRank=SUBSPECIES';
ELSEIF tax_rank  = 'variety' THEN
	appendix='&maxRank=VARIETY&minRank=SUBVARIETY';
END IF;
url_col2:=url_prefix||dataset_key||'/nameusage/search?q='||
		replace(taxon, ' ','%20')||appendix;
		--raise notice '%', url_col2;
FOR tmp in 
	WITH a as (
	SELECT fct_rmca_py_webservice as json_col_tmp FROM   
		fct_rmca_py_webservice(
		url_col2) ) ,
		b as (select *, a.json_col_tmp::json->'total' as total
			  
			  ,json_array_elements(json_col_tmp::json->'result') as item
			  FROM a),
		c as(
		select
			
		
			(json_array_elements(item::json->'classification')->'rank')::varchar parent_rank,
(json_array_elements(item::json->'classification')->'name')::varchar parent_name,*
		 FROM b),
		 d as (
		 SELECT distinct
			 url_col2 tmp_url_col2,
			 (c.total)::text::int as tmp_count_col ,
			 string_agg(trim('"' from parent_rank), '/') as parent_ranks, 
			 string_agg(trim('"' from parent_name), '/') as parent_names,
			  trim('"' from (c.item->'usage'->'id')::varchar) tmp_col_usage_key,
			 trim('"' from (c.item->'usage'->'name'->'scientificName')::varchar) tmp_col_scientific_name,
		 trim('"' from (c.item->'usage'->'name'->'authorship')::varchar) tmp_col_authorship,
			 trim('"' from (c.item->'usage'->'name'->'link')::varchar) as tmp_col_link,
			 trim('"' from (c.item->'usage'->'status')::varchar) as tmp_col_status,
			 trim('"' from (c.item->'usage'->'name'->'rank')::varchar) as tmp_col_rank,
			  trim('"' from c.json_col_tmp::varchar) as json_col_tmp
			 from c 
		 	GROUP BY 
			 url_col2,
			 (c.total)::text::int,
			 trim('"' from (c.item->'usage'->'id')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'scientificName')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'authorship')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'link')::varchar),
			 trim('"' from (c.item->'usage'->'status')::varchar),
			 trim('"' from (c.item->'usage'->'name'->'rank')::varchar),
				    trim('"' from c.json_col_tmp::varchar)
		 ) 
		 select 
		  *,  row_number() OVER () as rank_nb FROM d
		 LOOP
		   url_col:=tmp.tmp_url_col2;
		   count_col=tmp.tmp_count_col;
		   current_col:=tmp.rank_nb;
		   json_col:=tmp.json_col_tmp;
		   col_usage_key= tmp.tmp_col_usage_key;
		   col_scientific_name=tmp.tmp_col_scientific_name;
		   col_authorship=tmp.tmp_col_authorship;
		   col_link=tmp.tmp_col_link;
		   col_status= tmp.tmp_col_status;
		   col_rank=tmp.tmp_col_rank;
		   col_hierarchy_names:=tmp.parent_names;
		   col_hierarchy_ranks:=tmp.parent_ranks;
		return next;
		END LOOP;
END
$$;


ALTER FUNCTION darwin2.fct_rmca_taxon_to_catalogolife_api_rank(taxon character varying, tax_rank character varying, url_prefix character varying, dataset_key character varying) OWNER TO darwin2;

--
-- Name: fct_rmca_taxonomy_create_synonym(integer, integer, character varying, boolean, boolean, integer, boolean, boolean); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxonomy_create_synonym(valid_name_id integer, synonym_id integer, syn_relation character varying DEFAULT 'taxonomy'::character varying, p_valid_is_basionym boolean DEFAULT false, p_syn_is_basionym boolean DEFAULT false, p_import_ref integer DEFAULT NULL::integer, p_merge boolean DEFAULT false, with_exception boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	cpt_existing integer;
	existing_group integer;
	existing_basionym integer;
	valid_name varchar;
	syn_name varchar;
	next_in_group int;
	next_group int;
BEGIN
	IF valid_name_id=synonym_id THEN
		IF with_exception THEN
			SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
			SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
			RAISE EXCEPTION 'SAME_NAME_AS_VALID_AND_SYN % %',valid_name , syn_name;
		ELSE
			return NULL;			
		END IF;
	END IF;
	IF p_valid_is_basionym AND p_syn_is_basionym THEN
		IF with_exception THEN
			SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
			SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
			RAISE EXCEPTION 'CANNOT_DEFINE_TWO_BASIONYMS % %',valid_name , syn_name;
		ELSE
			return NULL;			
		END IF;
	END IF;
	PERFORM FROM darwin2.taxonomy WHERE id=valid_name_id;
	
	IF NOT FOUND THEN
		IF with_exception THEN
			SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
			RAISE EXCEPTION 'VALID_NAME_NOT_FOUND %',syn_name ;
		ELSE
			return NULL;			
		END IF;
	END IF;
	PERFORM FROM darwin2.taxonomy WHERE id=synonym_id;
	IF NOT FOUND THEN
		IF with_exception THEN
			SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
			RAISE EXCEPTION 'SYNONYM NOT FOUND %', valid_name;
		ELSE
			return NULL;			
		END IF;
	END IF;
	--test existing
	RAISE NOTICE 'test';
	WITH a AS (
			SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id 
		)
		SELECT COUNT(*) INTO cpt_existing FROM a WHERE a.group_id NOT IN (SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id );
	IF 	cpt_existing>0 THEN	
		RAISE NOTICE 'Valid name already in synonymy, but not the syn ';
			SELECT group_id INTO existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id ORDER BY group_id LIMIT 1 ;
			SELECT count(*) INTO cpt_existing FROM classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id AND group_id != existing_group; 
			IF cpt_existing >0 THEN
				RAISE NOTICE 'case of merge';
				IF p_merge THEN
					SELECT group_id INTO next_group FROM classification_synonymies WHERE referenced_relation=syn_relation AND 
						record_id=synonym_id AND group_id != existing_group order by group_id LIMIT 1; 
					UPDATE classification_synonymies SET group_id=existing_group, import_ref=p_import_ref WHERE group_id=next_group;
					RETURN existing_group;
				ELSE
					IF with_exception THEN
						SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
						SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
						RAISE EXCEPTION 'Can''t merge for % %',valid_name , syn_name;
					ELSE 
						return NULL;
					END IF;
					
				END IF;
			ELSE
				RAISE NOTICE 'do_import';
				SELECT COUNT(*) INTO existing_basionym FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND group_id=existing_group AND is_basionym=true;
				IF existing_basionym>0 AND (p_valid_is_basionym OR p_syn_is_basionym ) THEN
						IF with_exception THEN
							SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
							SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
							RAISE EXCEPTION 'GROUP HAS ALREADY ONE BASIONYM % %',valid_name , syn_name;
						ELSE 
							return NULL;
						END IF;
							
				ELSE			
					INSERT INTO darwin2.classification_synonymies (
												referenced_relation,
												record_id,
												group_id, 
												group_name, 
												is_basionym, 
												order_by, 
												import_ref ) VALUES 
												(
												syn_relation,
												synonym_id, 
												existing_group, 
												'synonym',
												p_syn_is_basionym, 
												0,
												p_import_ref ) ;
					RETURN existing_group;
				END IF;
			END IF;
	ELSE
		WITH a AS (
			SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id 
		)
		SELECT COUNT(*) INTO cpt_existing FROM a WHERE a.group_id NOT IN (SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id );
		
		IF 	cpt_existing>0 THEN	
			RAISE NOTICE 'Synonym name already in synonymy, but not the valid name ';
			SELECT group_id INTO existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id ORDER BY group_id LIMIT 1 ;
			SELECT count(*) INTO cpt_existing FROM classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id AND group_id != existing_group; 
			IF cpt_existing >0 THEN
				RAISE NOTICE 'case of merge'; 
				IF p_merge THEN
					SELECT group_id INTO next_group FROM classification_synonymies WHERE referenced_relation=syn_relation AND 
						record_id=valid_name_id AND group_id != existing_group order by group_id LIMIT 1; 
					UPDATE classification_synonymies SET group_id=existing_group, import_ref=p_import_ref WHERE group_id=next_group;
					RETURN existing_group;
				ELSE
					IF with_exception THEN
						SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
						SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
						RAISE EXCEPTION 'Can''t merge for % %',valid_name , syn_name;
					ELSE
						RETURN NULL;
					END IF;
				END IF;
			ELSE
				SELECT COUNT(*) INTO existing_basionym FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND group_id=existing_group AND is_basionym=true;
				IF existing_basionym>0 AND (p_valid_is_basionym OR p_syn_is_basionym ) THEN
					IF with_exception THEN
						SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
						SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
						RAISE EXCEPTION 'GROUP HAS ALREADY ONE BASIONYM % %',valid_name , syn_name;
					ELSE
						RETURN NULL;
					END IF;
				ELSE
					INSERT INTO darwin2.classification_synonymies (
												referenced_relation,
												record_id,
												group_id, 
												group_name, 
												is_basionym, 
												order_by, 
												import_ref ) VALUES 
												(
												syn_relation,
												valid_name_id, 
												existing_group, 
												'synonym',
												p_syn_is_basionym, 
												0,
												p_import_ref ) ;
					RETURN existing_group;
				END IF;
			END IF;
		ELSE
			WITH a AS (
				SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
				record_id=valid_name_id
			)
			SELECT COUNT(*) INTO cpt_existing FROM a INNER JOIN  darwin2.classification_synonymies ON a.group_id=classification_synonymies.group_id WHERE 
			referenced_relation=syn_relation AND record_id=synonym_id;
			IF cpt_existing>0 THEN				
				SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
				SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
				RAISE NOTICE 'SYN_ALREADY_EXISTS % %',valid_name , syn_name;
				RETURN NULL;
			ELSE
				--valid already exists
				SELECT group_id into existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND (record_id=valid_name_id ) 
					 ORDER BY group_id  LIMIT 1  ;
			
				IF existing_group IS NOT NULL THEN
					SELECT COUNT(*) INTO existing_basionym FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND group_id=existing_group AND is_basionym=true;
					IF existing_basionym>0 AND (p_valid_is_basionym OR p_syn_is_basionym ) THEN 
						If with_exception THEN
							SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
							SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
							RAISE EXCEPTION 'GROUP HAS ALREADY ONE BASIONYM % %',valid_name , syn_name;
						ELSE
							return NULL;
						END IF;
					ELSEIF   existing_basionym>0 THEN
						
						INSERT INTO darwin2.classification_synonymies (
							referenced_relation,
							record_id,
							group_id, 
							group_name, 
							is_basionym, 
							order_by , 
							import_ref) VALUES 
						(
							syn_relation,
							synonym_id, 
							existing_group, 
							'synonym',
							p_syn_is_basionym, 
							0,
							p_import_ref ) ;
						RETURN  existing_group;
					ELSE 
						--syn already exists 
						SELECT group_id into existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation 
							AND (record_id=synonym_id ) 
								 ORDER BY group_id  LIMIT 1  ;
								IF existing_basionym>0 AND (p_valid_is_basionym OR p_syn_is_basionym ) THEN 
									If with_exception THEN
										SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
										SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
										RAISE EXCEPTION 'GROUP HAS ALREADY ONE BASIONYM % %',valid_name , syn_name;
									ELSE
										RETURN NULL;
									END IF;
								ELSEIF existing_basionym>0 THEN
									INSERT INTO darwin2.classification_synonymies (
										referenced_relation,
										record_id,
										group_id, 
										group_name, 
										is_basionym, 
										order_by , 
										import_ref) VALUES 
										(
										syn_relation,
										valid_name_id, 
										existing_group, 
										'synonym',
										p_valid_is_basionym,
										0, 
										p_import_ref) ;
									RETURN  existing_group;
						
								ELSE --create new group
									SELECT COALESCE(MAX(group_id)) INTO next_group FROM  darwin2.classification_synonymies;
									INSERT INTO darwin2.classification_synonymies (
											referenced_relation,
											record_id,
											group_id, 
											group_name, 
											is_basionym, 
											order_by , 
										import_ref) VALUES 
										(
											syn_relation,
											valid_name_id, 
											next_group, 
											'synonym',
											p_syn_is_basionym, 
											0,
											p_import_ref ) ;
									INSERT INTO darwin2.classification_synonymies (
										referenced_relation,
										record_id,
										group_id, 
										group_name, 
										is_basionym, 
										order_by, 
										import_ref ) VALUES 
										(
										syn_relation,
										synonym_id, 
										next_group, 
										'synonym',
										p_syn_is_basionym, 
										0,
										p_import_ref ) ;
									RETURN  next_group;
								END IF;
					END IF;
					
				END IF;
			END IF;
		END IF;
	END IF;
RETURN -1;
END ;
$$;


ALTER FUNCTION darwin2.fct_rmca_taxonomy_create_synonym(valid_name_id integer, synonym_id integer, syn_relation character varying, p_valid_is_basionym boolean, p_syn_is_basionym boolean, p_import_ref integer, p_merge boolean, with_exception boolean) OWNER TO darwin2;

--
-- Name: fct_rmca_taxonomy_create_synonym_check_status(integer, integer, character varying, boolean, boolean, integer, boolean); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxonomy_create_synonym_check_status(valid_name_id integer, synonym_id integer, syn_relation character varying DEFAULT 'taxonomy'::character varying, p_valid_is_basionym boolean DEFAULT false, p_syn_is_basionym boolean DEFAULT false, p_import_ref integer DEFAULT NULL::integer, p_merge boolean DEFAULT false) RETURNS character varying
    LANGUAGE plpgsql
    AS $$
DECLARE
	cpt_existing integer;
	existing_group integer;
	existing_basionym integer;
	valid_name varchar;
	syn_name varchar;
	next_in_group int;
	next_group int;
BEGIN
	IF valid_name_id=synonym_id THEN
		SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
		SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
		return 'SAME_NAME_AS_VALID_AND_SYN';
	END IF;
	IF p_valid_is_basionym AND p_syn_is_basionym THEN
		SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
		SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
		return 'CANNOT_DEFINE_TWO_BASIONYMS';
	END IF;
	PERFORM FROM darwin2.taxonomy WHERE id=valid_name_id;
	
	IF NOT FOUND THEN
		SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
		return 'VALID_NAME_NOT_FOUND' ;
	END IF;
	PERFORM FROM darwin2.taxonomy WHERE id=synonym_id;
	IF NOT FOUND THEN
		SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
		return 'SYNONYM NOT FOUND';
	END IF;
	--test existing
	RAISE NOTICE 'test';
	WITH a AS (
			SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id 
		)
		SELECT COUNT(*) INTO cpt_existing FROM a WHERE a.group_id NOT IN (SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id );
	IF 	cpt_existing>0 THEN	
		RAISE NOTICE 'Valid name already in synonymy, but not the syn ';
			SELECT group_id INTO existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id ORDER BY group_id LIMIT 1 ;
			SELECT count(*) INTO cpt_existing FROM classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id AND group_id != existing_group; 
			IF cpt_existing >0 THEN
				return 'case_of_merge';
				
			ELSE
				return 'ok_valid_name_already_in_syn_but_not_the_synonym';
			END IF;
	ELSE
		WITH a AS (
			SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id 
		)
		SELECT COUNT(*) INTO cpt_existing FROM a WHERE a.group_id NOT IN (SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id );
		
		IF 	cpt_existing>0 THEN	
			RAISE NOTICE 'Synonym name already in synonymy, but not the valid name ';
			SELECT group_id INTO existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=synonym_id ORDER BY group_id LIMIT 1 ;
			SELECT count(*) INTO cpt_existing FROM classification_synonymies WHERE referenced_relation=syn_relation AND 
			record_id=valid_name_id AND group_id != existing_group; 
			IF cpt_existing >0 THEN
				return 'case of merge'; 
				
			ELSE
				SELECT COUNT(*) INTO existing_basionym FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND group_id=existing_group AND is_basionym=true;
				IF existing_basionym>0 AND (p_valid_is_basionym OR p_syn_is_basionym ) THEN 	
					SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
					SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
					return 'GROUP HAS ALREADY ONE BASIONYM';
				ELSE
					RETURN 'ok_syn_alreay_in_syn_but_not_the_valid_name';
				END IF;
			END IF;
		ELSE
			WITH a AS (
				SELECT group_id FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND 
				record_id=valid_name_id
			)
			SELECT COUNT(*) INTO cpt_existing FROM a INNER JOIN  darwin2.classification_synonymies ON a.group_id=classification_synonymies.group_id WHERE 
			referenced_relation=syn_relation AND record_id=synonym_id;
			IF cpt_existing>0 THEN
				SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
				SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
				return 'SYN_ALREADY_EXISTS';
				
			ELSE
				--valid already exists
				SELECT group_id into existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND (record_id=valid_name_id ) 
					 ORDER BY group_id  LIMIT 1  ;
			
				IF existing_group IS NOT NULL THEN
					SELECT COUNT(*) INTO existing_basionym FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation AND group_id=existing_group AND is_basionym=true;
					IF existing_basionym>0 AND (p_valid_is_basionym OR p_syn_is_basionym ) THEN 			
						
						return  'GROUP HAS ALREADY ONE BASIONYM';
					ELSEIF   existing_basionym>0 THEN
						
						
						RETURN  'ok';
					ELSE 
						--syn already exists 
						SELECT group_id into existing_group FROM  darwin2.classification_synonymies WHERE referenced_relation=syn_relation 
							AND (record_id=synonym_id ) 
								 ORDER BY group_id  LIMIT 1  ;
								IF existing_basionym>0 AND (p_valid_is_basionym OR p_syn_is_basionym ) THEN 			
									SELECT name INTO valid_name FROM taxonomy WHERE id= valid_name_id;
									SELECT name INTO syn_name FROM taxonomy WHERE id= synonym_id;
									return 'GROUP HAS ALREADY ONE BASIONYM';
								ELSEIF existing_basionym>0 THEN
									
									RETURN  'ok';
						
								ELSE --create new group
									
									RETURN  'ok';
								END IF;
					END IF;
					
				END IF;
			END IF;
		END IF;
	END IF;
RETURN -1;
END ;
$$;


ALTER FUNCTION darwin2.fct_rmca_taxonomy_create_synonym_check_status(valid_name_id integer, synonym_id integer, syn_relation character varying, p_valid_is_basionym boolean, p_syn_is_basionym boolean, p_import_ref integer, p_merge boolean) OWNER TO darwin2;

--
-- Name: fct_rmca_taxonomy_create_synonym_import(darwin2.staging_synonymies); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxonomy_create_synonym_import(line darwin2.staging_synonymies) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE returned boolean;
DECLARE code integer;
BEGIN
	returned:=false;
	IF COALESCE(line.imported, FALSE)=FALSE THEN
		select fct_rmca_taxonomy_create_synonym(line.valid_name_ref,
						line.syn_ref ,
						'taxonomy',
						COALESCE(line.valid_name_is_basionym,FALSE) ,
						FALSE,
						line.import_ref,
						FALSE,
						FALSE) INTO code
						;
		IF code is NOT NULL THEN
			If code >0 THEN
				UPDATE staging_synonymies SET imported=true WHERE staging_synonymies.id=line.id;
			END IF;
		END IF;
		returned:=TRUE;
	END IF;
	RETURN returned;
END
$$;


ALTER FUNCTION darwin2.fct_rmca_taxonomy_create_synonym_import(line darwin2.staging_synonymies) OWNER TO darwin2;

--
-- Name: fct_rmca_taxonomy_get_old_synonyms(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxonomy_get_old_synonyms(integer) RETURNS TABLE(taxon_id integer, id_log integer, referenced_relation character varying, old_record_id integer, user_name character varying, action character varying, modification_date_time timestamp without time zone, taxon_name character varying)
    LANGUAGE sql
    AS $_$ 
    
with a as (

select * from classification_synonymies_history where record_id=$1),
b as 
(select classification_synonymies_history.id as id_log,  classification_synonymies_history.record_id,
 classification_synonymies_history.group_id, 
 name, classification_synonymies_history.referenced_relation, 
 classification_synonymies_history.user_name,
 classification_synonymies_history.action,
  classification_synonymies_history.modification_date_time
 from classification_synonymies_history 
 inner join a on classification_synonymies_history.group_id=a.group_id
 and classification_synonymies_history.referenced_relation=a.referenced_relation 
inner join taxonomy on classification_synonymies_history.record_id=taxonomy.id
UNION
select classification_synonymies.id, classification_synonymies.record_id, classification_synonymies.group_id,
 name, classification_synonymies.referenced_relation, null, null,
 modification_date_time
 from classification_synonymies 
 inner join a on classification_synonymies.group_id=a.group_id and classification_synonymies.referenced_relation=a.referenced_relation 
inner join taxonomy on classification_synonymies.record_id=taxonomy.id
),

interm as (select classification_synonymies.record_id from classification_synonymies 
		   inner join a on classification_synonymies.group_id=a.group_id )


select distinct b.record_id as taxon_id,  id_log, b.referenced_relation, b.record_id, user_name, action, 
modification_date_time, name taxon_name  from b
where not exists (SELECT 1 FROM interm where interm.record_id=b.record_id) ;
 $_$;


ALTER FUNCTION darwin2.fct_rmca_taxonomy_get_old_synonyms(integer) OWNER TO darwin2;

--
-- Name: fct_rmca_taxonomy_get_other_synonyms(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxonomy_get_other_synonyms(integer) RETURNS TABLE(referenced_relation character varying, record_id integer, id integer, group_id integer, group_name character varying, is_basionym boolean, order_by integer, synonymy_record_id integer, original_synonym boolean, import_ref integer, syn_date timestamp without time zone, syn_date_mask integer)
    LANGUAGE sql
    AS $_$
 

with a as (

select * from classification_synonymies where record_id=$1),
b AS (
select * from classification_synonymies where group_id IN (SELECT DISTINCT group_id FROM a))
,
c as (select referenced_relation, record_id, id, group_id, group_name, is_basionym, order_by,
synonym_record_id, original_synonym, import_ref, syn_date, syn_date_mask  FROM classification_synonymies 
	WHERE record_id IN (SELECT distinct b.record_id FROM b)
	  AND classification_synonymies.group_id NOT IN (SELECT DISTINCT a.group_id FROM a)
	  AND record_id !=$1
	),
d as (select referenced_relation, record_id, id, group_id, group_name, is_basionym, order_by,
synonym_record_id, original_synonym, import_ref, syn_date, syn_date_mask from classification_synonymies where group_id in (SELECT distinct c.group_id FROM c) AND record_id !=$1)   
SELECT * FROM  d

 
$_$;


ALTER FUNCTION darwin2.fct_rmca_taxonomy_get_other_synonyms(integer) OWNER TO darwin2;

--
-- Name: fct_rmca_taxonomy_get_staging_hierarchy_recursive(integer); Type: FUNCTION; Schema: darwin2; Owner: darwin2
--

CREATE FUNCTION darwin2.fct_rmca_taxonomy_get_staging_hierarchy_recursive(integer) RETURNS TABLE(base_id integer, base_level_ref integer, base_name character varying, path character varying)
    LANGUAGE sql
    AS $_$
WITH RECURSIVE  staging_catalogue_tmp
AS

(
SELECT staging_catalogue.id as base_id,staging_catalogue.level_ref as base_level_ref, staging_catalogue.name as base_name, staging_catalogue.id, staging_catalogue.name, 
parent_ref_internal, staging_catalogue.import_ref
, staging_catalogue.level_Ref




 FROM staging_catalogue
LEFT JOIN imports
ON staging_catalogue.import_ref=imports.id


WHERE staging_catalogue.import_ref=$1
UNION
SELECT staging_catalogue_tmp.base_id,  staging_catalogue_tmp.base_level_ref, staging_catalogue_tmp.base_name,  s.id,s.name, s.parent_ref_internal, s.import_Ref
,s.level_Ref
 FROM staging_catalogue s
INNER JOIN staging_catalogue_tmp  
ON  s.id=staging_catalogue_tmp.parent_ref_internal




)


SELECT 
staging_catalogue_tmp.base_id::integer,staging_catalogue_tmp.base_level_ref::integer, staging_catalogue_tmp.base_name::varchar, '/'||string_agg(COALESCE(name||' ('||level_name||')',''), '/' ORDER BY level_ref)||'/'::varchar as path
FROM staging_catalogue_tmp 
LEFT JOIN catalogue_levels
ON level_ref=catalogue_levels.id
GROUP BY staging_catalogue_tmp.base_id,staging_catalogue_tmp.base_level_ref,
staging_catalogue_tmp.base_name

$_$;


