CREATE FUNCTION darwin2.set_path() RETURNS integer
    LANGUAGE plpgsql
    AS $_$
BEGIN
	SET search_path TO darwin2,darwin1,public;
	RETURN 1;
	EXCEPTION WHEN invalid_schema_name THEN
			SET search_path TO oracle,"$user",public;
	RETURN NULL;
END;
$_$;


