    LANGUAGE sql
    AS $$
 
 /*REFRESH MATERIALIZED VIEW ipt.mv_eml;
 REFRESH MATERIALIZED VIEW ipt.mv_properties;
 REFRESH MATERIALIZED VIEW ipt.mv_spatial;
 REFRESH MATERIALIZED VIEW ipt.mv_tag_to_country;
