 REFRESH MATERIALIZED VIEW ipt.mv_Darwin_ipt_rbins;
 REFRESH MATERIALIZED VIEW ipt.mv_Darwin_ipt_rbins_mof;*/
 refresh materialized view ipt.mv_tag_to_country with data;
refresh materialized view ipt.mv_tag_to_locations with data;
refresh materialized view ipt.mv_spatial with data;
refresh materialized view ipt.mv_properties with data;

refresh materialized view ipt.mv_darwin_ipt_rbins_mof with data;
refresh materialized view ipt.mv_darwin_ipt_rbins with data;
refresh materialized view ipt.mv_eml with data;
$$;


