--
-- Name: v_canathist_gtu_rwanda_stats; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_canathist_gtu_rwanda_stats AS
 WITH a AS (
         SELECT gtu_1.id,
            gtu_1.code,
            gtu_1.gtu_from_date_mask,
            gtu_1.gtu_from_date,
            gtu_1.gtu_to_date_mask,
            gtu_1.gtu_to_date,
            gtu_1.tag_values_indexed,
            gtu_1.latitude,
            gtu_1.longitude,
            gtu_1.lat_long_accuracy,
            gtu_1.elevation,
            gtu_1.elevation_accuracy,
            gtu_1.location,
            gtu_1.gtu_creation_date,
            gtu_1.import_ref,
            gtu_1.collector_refs,
            gtu_1.expedition_refs,
            gtu_1.collection_ref,
            gtu_1.latitude_dms_degree,
            gtu_1.latitude_dms_minutes,
            gtu_1.latitude_dms_seconds,
            gtu_1.latitude_dms_direction,
            gtu_1.longitude_dms_degree,
            gtu_1.longitude_dms_minutes,
            gtu_1.longitude_dms_seconds,
            gtu_1.longitude_dms_direction,
            gtu_1.latitude_utm,
            gtu_1.longitude_utm,
            gtu_1.utm_zone,
            gtu_1.coordinates_source,
            gtu_1.nagoya,
            gtu_1.expedition_ref,
            gtu_1.geom,
            gtu_1.iso3166,
            gtu_1.iso3166_subdivision
           FROM darwin2.gtu gtu_1
          WHERE public.st_intersects(gtu_1.geom, ( SELECT "RWA_adm0".geom
                   FROM wfs."RWA_adm0"))
        ), b AS (
         SELECT specimens.gtu_ref,
            specimens.gtu_country_tag_value,
            specimens.gtu_province_tag_value,
            specimens.gtu_others_tag_value,
            count(*) AS nb_database_records,
            sum(specimens.specimen_count_min) AS specimen_count_min,
            sum(specimens.specimen_count_max) AS specimen_count_max,
            specimens.type,
            count(*) AS cpt_type,
            (specimens.gtu_location)::character varying AS gtu_location,
            min(NULLIF(darwin2.fct_mask_date(specimens.gtu_from_date, specimens.gtu_from_date_mask), 'xxxx-xx-xx'::text)) AS min_date,
            max(NULLIF(darwin2.fct_mask_date(specimens.gtu_from_date, specimens.gtu_from_date_mask), 'xxxx-xx-xx'::text)) AS max_date
           FROM darwin2.specimens
          WHERE ((specimens.gtu_ref IN ( SELECT a.id
                   FROM a)) OR (((specimens.gtu_country_tag_indexed)::character varying)::text ~~ '%rwanda%'::text) OR (((specimens.gtu_country_tag_indexed)::character varying)::text ~~ '%ruanda%'::text))
          GROUP BY specimens.gtu_ref, specimens.type, specimens.gtu_country_tag_value, specimens.gtu_province_tag_value, specimens.gtu_others_tag_value, (specimens.gtu_location)::character varying
        )
 SELECT b.gtu_country_tag_value AS country_tag_value,
    b.gtu_province_tag_value AS province_tag_value,
    b.gtu_others_tag_value AS locality_desc,
    sum(b.nb_database_records) AS nb_database_records,
    sum(b.specimen_count_min) AS specimen_count_min,
    sum(b.specimen_count_max) AS specimen_count_max,
    string_agg(DISTINCT (b.type)::text, ';'::text ORDER BY (b.type)::text) AS types,
    ((b.gtu_location)::point)[1] AS long,
    ((b.gtu_location)::point)[0] AS lat,
    "substring"(min(b.min_date), 1, 4) AS min_date,
    "substring"(max(b.max_date), 1, 4) AS max_date
   FROM (b
     JOIN darwin2.gtu ON ((b.gtu_ref = gtu.id)))
  GROUP BY b.gtu_country_tag_value, b.gtu_province_tag_value, b.gtu_others_tag_value, b.gtu_location;


