--
-- Name: v_canathist_gtu_virunga_stats; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_canathist_gtu_virunga_stats AS
 WITH a AS (
         SELECT gtu_1.id,
            gtu_1.code,
            gtu_1.gtu_from_date_mask,
            gtu_1.gtu_from_date,
            gtu_1.gtu_to_date_mask,
            gtu_1.gtu_to_date,
            gtu_1.tag_values_indexed,
            gtu_1.latitude,
            gtu_1.longitude,
            gtu_1.lat_long_accuracy,
            gtu_1.location,
            gtu_1.elevation,
            gtu_1.elevation_accuracy,
            gtu_1.latitude_dms_degree,
            gtu_1.latitude_dms_minutes,
            gtu_1.latitude_dms_seconds,
            gtu_1.latitude_dms_direction,
            gtu_1.longitude_dms_degree,
            gtu_1.longitude_dms_minutes,
            gtu_1.longitude_dms_seconds,
            gtu_1.longitude_dms_direction,
            gtu_1.latitude_utm,
            gtu_1.longitude_utm,
            gtu_1.utm_zone,
            gtu_1.coordinates_source,
            gtu_1.gtu_creation_date,
            gtu_1.import_ref,
            gtu_1.iso3166,
            gtu_1.iso3166_subdivision,
            gtu_1.nagoya,
            gtu_1.collection_ref,
            gtu_1.collector_refs,
            gtu_1.expedition_refs,
            gtu_1.geom,
            gtu_1.expedition_ref
           FROM darwin2.gtu gtu_1
          WHERE public.st_intersects(gtu_1.geom, ( SELECT "CongoRDC_parcs_rgc_2019".geom
                   FROM wfs."CongoRDC_parcs_rgc_2019"
                  WHERE ("CongoRDC_parcs_rgc_2019".gid = 41)))
        ), b AS (
         SELECT specimens.gtu_ref,
            specimens.gtu_country_tag_value,
            specimens.gtu_province_tag_value,
            specimens.gtu_others_tag_value,
            count(*) AS nb_database_records,
            sum(specimens.specimen_count_min) AS specimen_count_min,
            sum(specimens.specimen_count_max) AS specimen_count_max,
            specimens.type,
            count(*) AS cpt_type,
            (specimens.gtu_location)::character varying AS gtu_location,
            min(NULLIF(darwin2.fct_mask_date(specimens.gtu_from_date, specimens.gtu_from_date_mask), 'xxxx-xx-xx'::text)) AS min_date,
            max(NULLIF(darwin2.fct_mask_date(specimens.gtu_from_date, specimens.gtu_from_date_mask), 'xxxx-xx-xx'::text)) AS max_date
           FROM darwin2.specimens
          WHERE ((specimens.gtu_ref IN ( SELECT a.id
                   FROM a)) OR (specimens.gtu_ref IN ( SELECT tags.gtu_ref
                   FROM darwin2.tags
                  WHERE (((tags.tag_indexed)::text ~~ '%virunga%'::text) OR ((tags.tag_indexed)::text ~~ '%parc%albert%'::text) OR ((tags.tag_indexed)::text ~~ '%albert%park%'::text) OR (lower((tags.tag)::text) ~~ '%p.n.a.%'::text)))))
          GROUP BY specimens.gtu_ref, specimens.type, specimens.gtu_country_tag_value, specimens.gtu_province_tag_value, specimens.gtu_others_tag_value, (specimens.gtu_location)::character varying
        )
 SELECT b.gtu_country_tag_value AS country_tag_value,
    b.gtu_province_tag_value AS province_tag_value,
    b.gtu_others_tag_value AS locality_desc,
    sum(b.nb_database_records) AS nb_database_records,
    sum(b.specimen_count_min) AS specimen_count_min,
    sum(b.specimen_count_max) AS specimen_count_max,
    string_agg(DISTINCT (b.type)::text, ';'::text ORDER BY (b.type)::text) AS types,
    ((b.gtu_location)::point)[0] AS long,
    ((b.gtu_location)::point)[1] AS lat,
    "substring"(min(b.min_date), 1, 4) AS min_date,
    "substring"(max(b.max_date), 1, 4) AS max_date
   FROM (b
     JOIN darwin2.gtu ON ((b.gtu_ref = gtu.id)))
  GROUP BY b.gtu_country_tag_value, b.gtu_province_tag_value, b.gtu_others_tag_value, b.gtu_location;


ALTER TABLE darwin2.v_canathist_gtu_virunga_stats OWNER TO darwin2;

--
-- Name: v_canathist_specimen_before_1960_arnaud; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_canathist_specimen_before_1960_arnaud AS
 SELECT v_collections_full_path_recursive.name_full_path,
    count(specimens.id) AS sum_records,
    sum(specimens.specimen_count_min) AS sum_physical_specimens
   FROM (darwin2.v_collections_full_path_recursive
     LEFT JOIN darwin2.specimens ON ((v_collections_full_path_recursive.id = specimens.collection_ref)))
  WHERE ((((v_collections_full_path_recursive.path)::text ~ '^/[0-9]+?/$'::text) OR ((v_collections_full_path_recursive.path)::text = '/'::text)) AND (date_part('year'::text, specimens.gtu_from_date) > (1)::double precision) AND (date_part('year'::text, specimens.gtu_from_date) < (1961)::double precision))
  GROUP BY v_collections_full_path_recursive.name_full_path, v_collections_full_path_recursive.path, v_collections_full_path_recursive.id
  ORDER BY v_collections_full_path_recursive.name_full_path;


ALTER TABLE darwin2.v_canathist_specimen_before_1960_arnaud OWNER TO darwin2;

--
-- Name: v_canathist_specimen_before_1960_arnaud_country; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_canathist_specimen_before_1960_arnaud_country AS
 SELECT v_collections_full_path_recursive.name_full_path,
    specimens.gtu_country_tag_indexed,
    count(specimens.id) AS sum_records,
    sum(specimens.specimen_count_min) AS sum_physical_specimens
   FROM (darwin2.v_collections_full_path_recursive
     LEFT JOIN darwin2.specimens ON ((v_collections_full_path_recursive.id = specimens.collection_ref)))
  WHERE ((((v_collections_full_path_recursive.path)::text ~ '^/[0-9]+?/$'::text) OR ((v_collections_full_path_recursive.path)::text = '/'::text)) AND (date_part('year'::text, specimens.gtu_from_date) > (1)::double precision) AND (date_part('year'::text, specimens.gtu_from_date) < (1961)::double precision))
  GROUP BY v_collections_full_path_recursive.name_full_path, v_collections_full_path_recursive.path, v_collections_full_path_recursive.id, specimens.gtu_country_tag_indexed
  ORDER BY v_collections_full_path_recursive.name_full_path;


ALTER TABLE darwin2.v_canathist_specimen_before_1960_arnaud_country OWNER TO darwin2;

--
-- Name: v_canathist_specimen_before_1960_arnaud_country_rdc; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_canathist_specimen_before_1960_arnaud_country_rdc AS
 SELECT v_canathist_specimen_before_1960_arnaud_country.name_full_path,
    string_agg(DISTINCT ((v_canathist_specimen_before_1960_arnaud_country.gtu_country_tag_indexed)::character varying)::text, (', '::character varying)::text) AS string_agg,
    sum(v_canathist_specimen_before_1960_arnaud_country.sum_records) AS nb_records,
    sum(v_canathist_specimen_before_1960_arnaud_country.sum_physical_specimens) AS sum_physical_specimens
   FROM darwin2.v_canathist_specimen_before_1960_arnaud_country
  WHERE (((((v_canathist_specimen_before_1960_arnaud_country.gtu_country_tag_indexed)::character varying)::text ~~ '%congo%'::text) OR (((v_canathist_specimen_before_1960_arnaud_country.gtu_country_tag_indexed)::character varying)::text ~~ '%zaire%'::text) OR (((v_canathist_specimen_before_1960_arnaud_country.gtu_country_tag_indexed)::character varying)::text ~~ '%zaïre%'::text)) AND (((v_canathist_specimen_before_1960_arnaud_country.gtu_country_tag_indexed)::character varying)::text !~~ '%braz%aville%'::text) AND (((v_canathist_specimen_before_1960_arnaud_country.gtu_country_tag_indexed)::character varying)::text !~~ '%francais%'::text))
  GROUP BY v_canathist_specimen_before_1960_arnaud_country.name_full_path;


ALTER TABLE darwin2.v_canathist_specimen_before_1960_arnaud_country_rdc OWNER TO darwin2;

--
-- Name: v_check_botany_taxo_meise; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_check_botany_taxo_meise AS
 WITH a AS (
         SELECT meise_taxonomy_bdi.sc_name,
            meise_taxonomy_bdi.rank,
            regexp_matches((meise_taxonomy_bdi.sc_name)::text, '([A-Z].*?)(\(|[A-Z])(.*)$'::text, 'g'::text) AS reg_out
           FROM darwin2.meise_taxonomy_bdi
          WHERE ((meise_taxonomy_bdi.rank)::text = 'Species_or_higher'::text)
        ), b AS (
         SELECT meise_taxonomy_bdi.sc_name,
            meise_taxonomy_bdi.rank,
            regexp_matches((meise_taxonomy_bdi.sc_name)::text, '([A-Z])(.*?)(\(|[A-Z])(.*)(subsp\.)(\s+)(.*?)(\(|[A-Z])(.*)$'::text, 'g'::text) AS reg_out
           FROM darwin2.meise_taxonomy_bdi
          WHERE ((meise_taxonomy_bdi.rank)::text = 'subspecies'::text)
        ), c AS (
         SELECT meise_taxonomy_bdi.sc_name,
            meise_taxonomy_bdi.rank,
            regexp_matches((meise_taxonomy_bdi.sc_name)::text, '([A-Z])(.*?)(\(|[A-Z])(.*)(var\.)(\s+)(.*?)(\(|[A-Z])(.*)$'::text, 'g'::text) AS reg_out
           FROM darwin2.meise_taxonomy_bdi
          WHERE ((meise_taxonomy_bdi.rank)::text = 'Variety'::text)
        )
 SELECT btrim(array_to_string(b.reg_out[1:2], ''::text)) AS species,
    btrim(array_to_string(b.reg_out[3:4], ''::text)) AS auth_sp,
    btrim(b.reg_out[7]) AS epith,
    btrim(array_to_string(b.reg_out[8:100], ''::text)) AS auth_epith,
    b.sc_name,
    b.rank,
    b.reg_out
   FROM b
UNION
 SELECT btrim(array_to_string(c.reg_out[1:2], ''::text)) AS species,
    btrim(array_to_string(c.reg_out[3:4], ''::text)) AS auth_sp,
    btrim(c.reg_out[7]) AS epith,
    btrim(array_to_string(c.reg_out[8:100], ''::text)) AS auth_epith,
    c.sc_name,
    c.rank,
    c.reg_out
   FROM c
UNION
 SELECT a.reg_out[1] AS species,
    array_to_string(a.reg_out[2:100], ''::text) AS auth_sp,
    NULL::text AS epith,
    NULL::text AS auth_epith,
    a.sc_name,
    a.rank,
    a.reg_out
   FROM a;


ALTER TABLE darwin2.v_check_botany_taxo_meise OWNER TO darwin2;

--
-- Name: v_check_botany_meise_sp_problem2; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_check_botany_meise_sp_problem2 AS
 SELECT v_check_botany_taxo_meise.sc_name,
    regexp_matches((v_check_botany_taxo_meise.sc_name)::text, '([A-Z])(.*?)([A-Z]|\()(.*?)(\s[^A-Z|^&](.*))$'::text, 'g'::text) AS regexp_matches
   FROM darwin2.v_check_botany_taxo_meise
  WHERE (((v_check_botany_taxo_meise.rank)::text = 'Species_or_higher'::text) AND ((v_check_botany_taxo_meise.sc_name)::text !~~ '% ex %'::text) AND ((v_check_botany_taxo_meise.sc_name)::text !~~ '% f.%'::text) AND ((v_check_botany_taxo_meise.sc_name)::text !~~ '% al.%'::text) AND ((v_check_botany_taxo_meise.sc_name)::text !~~ '% de %'::text) AND ((v_check_botany_taxo_meise.sc_name)::text !~~ '% der %'::text));


ALTER TABLE darwin2.v_check_botany_meise_sp_problem2 OWNER TO darwin2;

--
-- Name: v_check_botany_taxo_meise_pb_epith; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_check_botany_taxo_meise_pb_epith AS
 SELECT v_check_botany_taxo_meise.species,
    v_check_botany_taxo_meise.epith,
    count(DISTINCT v_check_botany_taxo_meise.auth_epith) AS count,
    array_agg(v_check_botany_taxo_meise.sc_name) AS array_agg
   FROM darwin2.v_check_botany_taxo_meise
  GROUP BY v_check_botany_taxo_meise.species, v_check_botany_taxo_meise.epith
 HAVING (count(DISTINCT v_check_botany_taxo_meise.auth_epith) > 1);


ALTER TABLE darwin2.v_check_botany_taxo_meise_pb_epith OWNER TO darwin2;

--
-- Name: v_check_botany_taxo_meise_sp_problem; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_check_botany_taxo_meise_sp_problem AS
 SELECT v_check_botany_taxo_meise.species,
    count(DISTINCT v_check_botany_taxo_meise.auth_sp) AS auth_list,
    array_agg(v_check_botany_taxo_meise.auth_sp) AS species_list,
    array_agg(v_check_botany_taxo_meise.sc_name) AS fullnames_list
   FROM darwin2.v_check_botany_taxo_meise
  GROUP BY v_check_botany_taxo_meise.species
 HAVING (count(DISTINCT v_check_botany_taxo_meise.auth_sp) > 1);


ALTER TABLE darwin2.v_check_botany_taxo_meise_sp_problem OWNER TO darwin2;

--
-- Name: v_codes_series; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_codes_series AS
 SELECT codes.referenced_relation,
    codes.record_id,
    codes.id,
    codes.code_category,
    codes.code_prefix,
    codes.code_prefix_separator,
    codes.code,
    codes.code_suffix,
    codes.code_suffix_separator,
    codes.full_code_indexed,
    codes.code_date,
    codes.code_date_mask,
    codes.code_num,
    COALESCE(mv_code_expand_interval.interm_code_full, btrim((((((COALESCE(codes.code_prefix, ''::character varying))::text || (COALESCE(codes.code_prefix_separator, ''::character varying))::text) || (COALESCE(codes.code, ''::character varying))::text) || (COALESCE(codes.code_suffix_separator, ''::character varying))::text) || (COALESCE(codes.code_suffix, ''::character varying))::text))) AS code_full,
    COALESCE((((((mv_code_expand_interval.interm_code_full || ' (serie '::text) || mv_code_expand_interval.begin_serie) || '-'::text) || mv_code_expand_interval.end_serie) || ')'::text), btrim((((((COALESCE(codes.code_prefix, ''::character varying))::text || (COALESCE(codes.code_prefix_separator, ''::character varying))::text) || (COALESCE(codes.code, ''::character varying))::text) || (COALESCE(codes.code_suffix_separator, ''::character varying))::text) || (COALESCE(codes.code_suffix, ''::character varying))::text))) AS code_full_serie,
    COALESCE(mv_code_expand_interval.interm_code_indexed, codes.full_code_indexed) AS serie_indexed
   FROM (darwin2.codes
     LEFT JOIN darwin2.mv_code_expand_interval ON ((codes.id = mv_code_expand_interval.id)));


ALTER TABLE darwin2.v_codes_series OWNER TO darwin2;

--
-- Name: v_rmca_collections_path_as_text; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_rmca_collections_path_as_text AS
 SELECT collections.id,
    collections.collection_type,
    collections.code,
    collections.name,
    collections.name_indexed,
    collections.institution_ref,
    collections.main_manager_ref,
    collections.parent_ref,
    collections.path,
    collections.code_auto_increment,
    collections.code_last_value,
    collections.code_prefix,
    collections.code_prefix_separator,
    collections.code_suffix,
    collections.code_suffix_separator,
    collections.is_public,
    collections.code_specimen_duplicate,
    collections.staff_ref,
    collections.code_auto_increment_for_insert_only,
    collections.code_mask,
    collections.allow_duplicates,
    string_agg((b.name)::text, '/'::text ORDER BY (collections.coll_path)::integer) AS collection_path_text,
    string_agg((b.code)::text, '/'::text ORDER BY (collections.coll_path)::integer) AS collection_path_code,
    string_agg((b.name_indexed)::text, '/'::text ORDER BY (collections.coll_path)::integer) AS collection_path_indexed,
    (array_agg((b.name)::text ORDER BY (collections.coll_path)::integer))[1] AS collection_main_text,
    (array_agg((b.code)::text ORDER BY (collections.coll_path)::integer))[1] AS collection_main_code,
    (array_agg((b.name_indexed)::text ORDER BY (collections.coll_path)::integer))[1] AS collection_main_indexed
   FROM (( SELECT DISTINCT collections_1.id,
            collections_1.collection_type,
            collections_1.code,
            collections_1.name,
            collections_1.name_indexed,
            collections_1.institution_ref,
            collections_1.main_manager_ref,
            collections_1.parent_ref,
            collections_1.path,
            regexp_split_to_table(btrim(((collections_1.path)::text || ((collections_1.id)::character varying)::text), '/'::text), '/'::text) AS coll_path,
            collections_1.code_auto_increment,
            collections_1.code_last_value,
            collections_1.code_prefix,
            collections_1.code_prefix_separator,
            collections_1.code_suffix,
            collections_1.code_suffix_separator,
            collections_1.is_public,
            collections_1.code_specimen_duplicate,
            collections_1.staff_ref,
            collections_1.code_auto_increment_for_insert_only,
            collections_1.code_mask,
            collections_1.allow_duplicates
           FROM darwin2.collections collections_1) collections
     LEFT JOIN darwin2.collections b ON (((collections.coll_path)::integer = b.id)))
  GROUP BY collections.id, collections.collection_type, collections.code, collections.name, collections.name_indexed, collections.institution_ref, collections.main_manager_ref, collections.parent_ref, collections.path, collections.code_auto_increment, collections.code_last_value, collections.code_prefix, collections.code_prefix_separator, collections.code_suffix, collections.code_suffix_separator, collections.is_public, collections.code_specimen_duplicate, collections.staff_ref, collections.code_auto_increment_for_insert_only, collections.code_mask, collections.allow_duplicates;


ALTER TABLE darwin2.v_rmca_collections_path_as_text OWNER TO darwin2;

--
-- Name: v_collection_stats_yearly_new_taxa_build; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_collection_stats_yearly_new_taxa_build AS
 WITH base_a AS (
         SELECT specimens.id,
            specimens.taxon_ref,
            unnest(string_to_array((((specimens.taxon_path)::text || ((specimens.taxon_ref)::character varying)::text) || '/'::text), '/'::text)) AS taxon_path_ref,
            COALESCE(date_part('year'::text, (specimens.specimen_creation_date)::date), '2012'::double precision) AS year
           FROM darwin2.specimens
        ), b AS (
         SELECT DISTINCT base_a.taxon_path_ref,
            min(base_a.year) AS min_year
           FROM base_a
          WHERE (base_a.taxon_path_ref <> ''::text)
          GROUP BY base_a.taxon_path_ref
        ), c AS (
         SELECT DISTINCT base_a.id,
            base_a.taxon_ref,
            base_a.taxon_path_ref,
            base_a.year
           FROM (b
             JOIN base_a ON (((b.taxon_path_ref = base_a.taxon_path_ref) AND (b.min_year = base_a.year))))
        ), d AS (
         SELECT min(c.id) AS min_id,
            c.taxon_ref,
            c.taxon_path_ref,
            c.year
           FROM c
          GROUP BY c.taxon_ref, c.taxon_path_ref, c.year
        ), e AS (
         SELECT DISTINCT d.year,
            d.min_id,
            d.taxon_path_ref,
            specimens.collection_ref,
            v_rmca_collections_path_as_text.name AS collection_name,
            v_rmca_collections_path_as_text.collection_path_text,
            v_rmca_collections_path_as_text.collection_path_code,
            catalogue_levels.id,
            catalogue_levels.level_name,
            taxonomy.name AS taxon_name
           FROM ((((d
             JOIN darwin2.specimens ON ((d.min_id = specimens.id)))
             JOIN darwin2.v_rmca_collections_path_as_text ON ((specimens.collection_ref = v_rmca_collections_path_as_text.id)))
             JOIN darwin2.taxonomy ON (((d.taxon_path_ref)::integer = taxonomy.id)))
             JOIN darwin2.catalogue_levels ON ((taxonomy.level_ref = catalogue_levels.id)))
        )
 SELECT e.year,
    e.min_id,
    e.taxon_path_ref,
    e.collection_ref,
    e.collection_name,
    e.collection_path_text,
    e.collection_path_code,
    e.id,
    e.level_name,
    e.taxon_name
   FROM e;


ALTER TABLE darwin2.v_collection_stats_yearly_new_taxa_build OWNER TO darwin2;

--
-- Name: v_collection_stats_yearly_new_taxa; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_collection_stats_yearly_new_taxa AS
 SELECT v_collection_stats_yearly_new_taxa_build.year,
    v_collection_stats_yearly_new_taxa_build.collection_ref,
    v_collection_stats_yearly_new_taxa_build.collection_name,
    v_collection_stats_yearly_new_taxa_build.collection_path_text,
    v_collection_stats_yearly_new_taxa_build.collection_path_code,
    v_collection_stats_yearly_new_taxa_build.id AS id_level,
    v_collection_stats_yearly_new_taxa_build.level_name,
    count(v_collection_stats_yearly_new_taxa_build.taxon_path_ref) AS new_taxa
   FROM darwin2.v_collection_stats_yearly_new_taxa_build
  GROUP BY v_collection_stats_yearly_new_taxa_build.year, v_collection_stats_yearly_new_taxa_build.collection_ref, v_collection_stats_yearly_new_taxa_build.collection_name, v_collection_stats_yearly_new_taxa_build.collection_path_text, v_collection_stats_yearly_new_taxa_build.collection_path_code, v_collection_stats_yearly_new_taxa_build.id, v_collection_stats_yearly_new_taxa_build.level_name
  ORDER BY v_collection_stats_yearly_new_taxa_build.year, v_collection_stats_yearly_new_taxa_build.collection_path_text, v_collection_stats_yearly_new_taxa_build.id;


ALTER TABLE darwin2.v_collection_stats_yearly_new_taxa OWNER TO darwin2;

--
-- Name: v_collection_stats_yearly_spec_count; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_collection_stats_yearly_spec_count AS
 WITH a AS (
         SELECT v_rmca_collections_path_as_text.id,
            v_rmca_collections_path_as_text.collection_type,
            v_rmca_collections_path_as_text.code,
            v_rmca_collections_path_as_text.name,
            v_rmca_collections_path_as_text.name_indexed,
            v_rmca_collections_path_as_text.institution_ref,
            v_rmca_collections_path_as_text.main_manager_ref,
            v_rmca_collections_path_as_text.parent_ref,
            v_rmca_collections_path_as_text.path,
            v_rmca_collections_path_as_text.code_auto_increment,
            v_rmca_collections_path_as_text.code_last_value,
            v_rmca_collections_path_as_text.code_prefix,
            v_rmca_collections_path_as_text.code_prefix_separator,
            v_rmca_collections_path_as_text.code_suffix,
            v_rmca_collections_path_as_text.code_suffix_separator,
            v_rmca_collections_path_as_text.is_public,
            v_rmca_collections_path_as_text.code_specimen_duplicate,
            v_rmca_collections_path_as_text.staff_ref,
            v_rmca_collections_path_as_text.code_auto_increment_for_insert_only,
            v_rmca_collections_path_as_text.code_mask,
            v_rmca_collections_path_as_text.allow_duplicates,
            v_rmca_collections_path_as_text.collection_path_text,
            v_rmca_collections_path_as_text.collection_path_code,
            v_rmca_collections_path_as_text.collection_path_indexed,
            v_rmca_collections_path_as_text.collection_main_text,
            v_rmca_collections_path_as_text.collection_main_code,
            v_rmca_collections_path_as_text.collection_main_indexed
           FROM darwin2.v_rmca_collections_path_as_text
        ), b AS (
         SELECT COALESCE(date_part('year'::text, specimens.specimen_creation_date), '2012'::double precision) AS year,
            a.id AS id_collection,
            a.name,
            a.collection_path_text,
            a.collection_path_code,
            count(specimens.id) AS count,
            sum(specimens.specimen_count_min) AS physical_specimen_count_min,
            sum(specimens.specimen_count_max) AS physical_specimen_count_max
           FROM (darwin2.specimens
             LEFT JOIN a ON ((specimens.collection_ref = a.id)))
          GROUP BY a.id, a.name, a.collection_path_text, a.collection_path_code, COALESCE(date_part('year'::text, specimens.specimen_creation_date), '2012'::double precision)
          ORDER BY COALESCE(date_part('year'::text, specimens.specimen_creation_date), '2012'::double precision), a.collection_path_code
        )
 SELECT b.year,
    b.id_collection,
    b.name,
    b.collection_path_text,
    b.collection_path_code,
    b.count,
    b.physical_specimen_count_min,
    b.physical_specimen_count_max,
    (((b.physical_specimen_count_min)::numeric(12,2) / (b.count)::numeric(12,2)))::numeric(12,2) AS physical_specimen_per_record_min,
    (((b.physical_specimen_count_max)::numeric(12,2) / (b.count)::numeric(12,2)))::numeric(12,2) AS physical_specimen_per_record_max
   FROM b;


ALTER TABLE darwin2.v_collection_stats_yearly_spec_count OWNER TO darwin2;

