          GROUP BY a.id, a.name, a.collection_path_text, a.collection_path_code, COALESCE(date_part('year'::text, (specimens.specimen_creation_date)::date), '2012'::double precision), specimens.type
          ORDER BY COALESCE(date_part('year'::text, (specimens.specimen_creation_date)::date), '2012'::double precision), a.collection_path_code, specimens.type
