   FROM (darwin2.v_collections_full_path_recursive
     LEFT JOIN darwin2.identifiers ON (((v_collections_full_path_recursive.id = identifiers.record_id) AND ((identifiers.referenced_relation)::text = 'collections'::text) AND (lower((identifiers.protocol)::text) = 'grscicoll code'::text))));


