--
-- Name: v_collections_full_path_recursive_grscicoll_code_spec_count; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_collections_full_path_recursive_grscicoll_code_spec_count AS
 WITH spec AS (
         SELECT specimens.collection_ref,
            count(specimens.id) AS count_record,
            sum(specimens.specimen_count_min) AS specimen_count_min,
            sum(specimens.specimen_count_max) AS specimen_count_max
           FROM darwin2.specimens
          GROUP BY specimens.collection_ref
        ), p_types AS (
         SELECT specimens.collection_ref,
            count(specimens.id) AS count_record,
            sum(specimens.specimen_count_min) AS specimen_count_min,
            sum(specimens.specimen_count_max) AS specimen_count_max
           FROM darwin2.specimens
          WHERE ((lower((COALESCE(specimens.type, 'specimen'::character varying))::text) !~~ 'specimen%'::text) AND ((specimens.type)::text <> ''::text) AND (specimens.type IS NOT NULL))
          GROUP BY specimens.collection_ref
        )
 SELECT v_collections_full_path_recursive_grscicoll.id,
    v_collections_full_path_recursive_grscicoll.collection_type,
    v_collections_full_path_recursive_grscicoll.code,
    v_collections_full_path_recursive_grscicoll.grscicoll_code,
    v_collections_full_path_recursive_grscicoll.name,
    v_collections_full_path_recursive_grscicoll.name_indexed,
    v_collections_full_path_recursive_grscicoll.allow_duplicates,
    v_collections_full_path_recursive_grscicoll.code_full_path,
    v_collections_full_path_recursive_grscicoll.name_full_path,
    v_collections_full_path_recursive_grscicoll.name_indexed_full_path,
    spec.count_record,
    spec.specimen_count_min,
    spec.specimen_count_max,
    p_types.count_record AS types_count_record,
    p_types.specimen_count_min AS types_specimen_count_min,
    p_types.specimen_count_max AS types_specimen_count_max,
    v_collections_full_path_recursive_grscicoll.is_public,
    v_collections_full_path_recursive_grscicoll.path
   FROM ((darwin2.v_collections_full_path_recursive_grscicoll
     LEFT JOIN spec ON ((v_collections_full_path_recursive_grscicoll.id = spec.collection_ref)))
     LEFT JOIN p_types ON ((v_collections_full_path_recursive_grscicoll.id = p_types.collection_ref)))
  ORDER BY v_collections_full_path_recursive_grscicoll.name_full_path;


ALTER TABLE darwin2.v_collections_full_path_recursive_grscicoll_code_spec_count OWNER TO darwin2;

