--
-- Name: v_collectors_normalized_activity_stats; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_collectors_normalized_activity_stats AS
 WITH a0 AS (
         SELECT v_collections_full_path_recursive.id,
            v_collections_full_path_recursive.collection_type,
            v_collections_full_path_recursive.code,
            v_collections_full_path_recursive.name,
            v_collections_full_path_recursive.name_indexed,
            v_collections_full_path_recursive.institution_ref,
            v_collections_full_path_recursive.main_manager_ref,
            v_collections_full_path_recursive.parent_ref,
            v_collections_full_path_recursive.path,
            v_collections_full_path_recursive.code_auto_increment,
            v_collections_full_path_recursive.code_last_value,
            v_collections_full_path_recursive.code_prefix,
            v_collections_full_path_recursive.code_prefix_separator,
            v_collections_full_path_recursive.code_suffix,
            v_collections_full_path_recursive.code_suffix_separator,
            v_collections_full_path_recursive.is_public,
            v_collections_full_path_recursive.code_specimen_duplicate,
            v_collections_full_path_recursive.staff_ref,
            v_collections_full_path_recursive.code_auto_increment_for_insert_only,
            v_collections_full_path_recursive.code_mask,
            v_collections_full_path_recursive.allow_duplicates,
            v_collections_full_path_recursive.publish_to_gbif,
            v_collections_full_path_recursive.profile,
            v_collections_full_path_recursive.title_en,
            v_collections_full_path_recursive.title_nl,
            v_collections_full_path_recursive.title_fr,
            v_collections_full_path_recursive.code_ai_inherit,
            v_collections_full_path_recursive.preferred_taxonomy,
            v_collections_full_path_recursive.uid,
            v_collections_full_path_recursive.nagoya,
            v_collections_full_path_recursive.code_full_path,
            v_collections_full_path_recursive.name_full_path,
            v_collections_full_path_recursive.name_indexed_full_path
           FROM darwin2.v_collections_full_path_recursive
        ), a AS (
         SELECT catalogue_people.referenced_relation,
            catalogue_people.record_id,
            catalogue_people.people_type,
            catalogue_people.people_sub_type,
            catalogue_people.order_by,
            catalogue_people.people_ref,
            people.formated_name
           FROM (darwin2.catalogue_people
             LEFT JOIN darwin2.people ON ((catalogue_people.people_ref = people.id)))
          WHERE ((catalogue_people.people_type)::text = 'collector'::text)
        ), b AS (
         SELECT DISTINCT a.people_ref,
            a.formated_name
           FROM a
        ), c AS (
         SELECT b.people_ref,
            b.formated_name,
            darwin2.rmca_split_author_group(b.formated_name) AS ga
           FROM b
        ), d AS (
         SELECT c.people_ref,
            c.formated_name,
            c.ga,
            unnest(c.ga) AS collector_normalize
           FROM c
        ), e AS (
         SELECT d.people_ref,
            d.formated_name,
            d.ga,
            d.collector_normalize,
            a.record_id,
            specimens.collection_ref,
            a0.name_full_path,
            specimens.specimen_count_min,
            temporal_information.from_date AS gtu_from_date,
            temporal_information.to_date AS gtu_to_date,
            specimens.gtu_country_tag_value AS countries,
            specimens.gtu_others_tag_value AS localities
           FROM ((((a
             LEFT JOIN d ON ((a.people_ref = d.people_ref)))
             LEFT JOIN darwin2.specimens ON ((a.record_id = specimens.id)))
             LEFT JOIN a0 ON ((specimens.collection_ref = a0.id)))
             LEFT JOIN darwin2.temporal_information ON ((specimens.id = temporal_information.specimen_ref)))
          GROUP BY d.people_ref, d.formated_name, d.ga, d.collector_normalize, a.record_id, specimens.collection_ref, a0.name_full_path, specimens.specimen_count_min, specimens.gtu_country_tag_value, specimens.gtu_others_tag_value, temporal_information.from_date, temporal_information.to_date
        ), f00 AS (
         SELECT DISTINCT e.collector_normalize,
            e.record_id,
            e.specimen_count_min,
            COALESCE(e.name_full_path, 'UNK'::character varying) AS collection
           FROM e
        ), f0 AS (
         SELECT f00.collector_normalize,
            count(DISTINCT f00.record_id) AS nb_records,
            sum(f00.specimen_count_min) AS nb_physical_specimens
           FROM f00
          GROUP BY f00.collector_normalize
        ), f01 AS (
         SELECT f00.collector_normalize,
            f00.collection,
            count(DISTINCT f00.record_id) AS nb_records_by_collection,
            sum(f00.specimen_count_min) AS nb_physical_specimens_by_collection
           FROM f00
          GROUP BY f00.collector_normalize, f00.collection
        ), f1 AS (
         SELECT f01.collector_normalize,
            (json_object_agg(f01.collection, f01.nb_records_by_collection))::character varying AS records_by_collection,
            (json_object_agg(f01.collection, f01.nb_physical_specimens_by_collection))::character varying AS physical_specimens_by_collection
           FROM f01
          GROUP BY f01.collector_normalize
        ), f02a AS (
         SELECT DISTINCT e.collector_normalize,
            e.record_id,
            e.specimen_count_min,
            COALESCE(e.countries, 'UNK'::character varying) AS countries
           FROM e
        ), f02b AS (
         SELECT f02a.collector_normalize,
            f02a.countries,
            count(DISTINCT f02a.record_id) AS nb_records_by_country,
            sum(f02a.specimen_count_min) AS nb_physical_specimens_by_country
           FROM f02a
          GROUP BY f02a.collector_normalize, f02a.countries
        ), f2 AS (
         SELECT f02b.collector_normalize,
            (json_object_agg(f02b.countries, f02b.nb_records_by_country))::character varying AS records_by_country,
            (json_object_agg(f02b.countries, f02b.nb_physical_specimens_by_country))::character varying AS physical_specimens_by_country
           FROM f02b
          GROUP BY f02b.collector_normalize
        ), f3 AS (
         SELECT e.collector_normalize,
            min(e.gtu_from_date) AS activity_date_begin,
            max(e.gtu_from_date) AS activity_date_end_1,
            max(e.gtu_to_date) AS activity_date_end_2
           FROM e
          GROUP BY e.collector_normalize
        ), f04 AS (
         SELECT DISTINCT e.collector_normalize,
            COALESCE(e.countries, 'UNK'::character varying) AS countries,
            e.localities
           FROM e
        ), f4 AS (
         SELECT DISTINCT f04.collector_normalize,
            (json_object_agg(f04.countries, f04.localities))::character varying AS list_localities
           FROM f04
          GROUP BY f04.collector_normalize
        ), g AS (
         SELECT e.collector_normalize,
            date_part('year'::text, NULLIF(f3.activity_date_begin, '0001-01-01 00:00:00'::timestamp without time zone)) AS activity_date_begin,
            date_part('year'::text, NULLIF(NULLIF(f3.activity_date_end_1, '2038-12-31 00:00:00'::timestamp without time zone), '0001-01-01 00:00:00'::timestamp without time zone)) AS activity_date_end_1,
            date_part('year'::text, NULLIF(f3.activity_date_end_2, '2038-12-31 00:00:00'::timestamp without time zone)) AS activity_date_end_2,
            f0.nb_records,
            f0.nb_physical_specimens,
            f1.records_by_collection,
            f1.physical_specimens_by_collection,
            f2.records_by_country,
            f2.physical_specimens_by_country,
            f4.list_localities,
            string_agg(DISTINCT ((e.people_ref)::character varying)::text, ';'::text ORDER BY ((e.people_ref)::character varying)::text) AS people_ref,
            string_agg(DISTINCT (e.formated_name)::text, ';'::text ORDER BY (e.formated_name)::text) AS formated_name_labels
           FROM (((((e
             LEFT JOIN f0 ON (((e.collector_normalize)::text = (f0.collector_normalize)::text)))
             LEFT JOIN f1 ON (((e.collector_normalize)::text = (f1.collector_normalize)::text)))
             LEFT JOIN f2 ON (((e.collector_normalize)::text = (f2.collector_normalize)::text)))
             LEFT JOIN f3 ON (((e.collector_normalize)::text = (f3.collector_normalize)::text)))
             LEFT JOIN f4 ON (((e.collector_normalize)::text = (f4.collector_normalize)::text)))
          GROUP BY e.collector_normalize, f3.activity_date_begin, f3.activity_date_end_1, f3.activity_date_end_2, f0.nb_records, f0.nb_physical_specimens, f1.records_by_collection, f1.physical_specimens_by_collection, f2.records_by_country, f2.physical_specimens_by_country, f4.list_localities
        )
 SELECT g.collector_normalize,
    g.activity_date_begin,
    g.activity_date_end_1,
    g.activity_date_end_2,
    g.nb_records,
    g.nb_physical_specimens,
    g.records_by_collection,
    g.physical_specimens_by_collection,
    g.records_by_country,
    g.physical_specimens_by_country,
    g.list_localities,
    g.people_ref,
    g.formated_name_labels
   FROM g;


ALTER TABLE darwin2.v_collectors_normalized_activity_stats OWNER TO darwin2;

--
-- Name: v_darwin_ipt_taxonomy; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_darwin_ipt_taxonomy AS
 SELECT taxonomy.id AS darwin_id,
    taxonomy.name AS scientificname,
    catalogue_levels.level_name AS taxonrank,
    catalogue_levels.level_name AS verbatimtaxonrank,
    darwin2.fct_rmca_sort_taxon_get_parent_level_text(taxonomy.id, 2) AS kingdom,
    darwin2.fct_rmca_sort_taxon_get_parent_level_text(taxonomy.id, 4) AS phylum,
    darwin2.fct_rmca_sort_taxon_get_parent_level_text(taxonomy.id, 12) AS class,
    darwin2.fct_rmca_sort_taxon_get_parent_level_text(taxonomy.id, 28) AS "order",
    darwin2.fct_rmca_sort_taxon_get_parent_level_text(taxonomy.id, 34) AS family,
    darwin2.fct_rmca_sort_taxon_get_parent_level_text(taxonomy.id, 41) AS genus,
    replace((darwin2.fct_rmca_sort_taxon_path_alphabetically_not_indexed(taxonomy.path))::text, '/'::text, '|'::text) AS higherclassification,
    taxonomy.path,
    ((taxonomy.path)::text || ((taxonomy.id)::character varying)::text) AS full_path
   FROM (darwin2.taxonomy
     LEFT JOIN darwin2.catalogue_levels ON ((taxonomy.level_ref = catalogue_levels.id)));


ALTER TABLE darwin2.v_darwin_ipt_taxonomy OWNER TO darwin2;

--
-- Name: vernacular_names; Type: TABLE; Schema: darwin2; Owner: postgres
