--
-- Name: v_get_user_tracking_jim_locat; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_get_user_tracking_jim_locat AS
 WITH a AS (
         SELECT DISTINCT users_tracking.record_id,
            (users_tracking.new_value OPERATOR(public.-) users_tracking.old_value) AS modified,
            (users_tracking.old_value OPERATOR(public.-) users_tracking.new_value) AS "?column?",
            users_tracking.action
           FROM darwin2.users_tracking
          WHERE ((users_tracking.user_ref = 47715) AND ((users_tracking.referenced_relation)::text = 'specimens'::text) AND (((users_tracking.action)::text = 'insert'::text) OR ((users_tracking.action)::text = 'update'::text)))
        )
 SELECT replace((v_collections_full_path_recursive.name_full_path)::text, '|'::text, '/'::text) AS collection,
    (((((COALESCE(codes.code_prefix, ''::character varying))::text || (COALESCE(codes.code_prefix_separator, ''::character varying))::text) || (COALESCE(codes.code, ''::character varying))::text) || (COALESCE(codes.code_suffix_separator, ''::character varying))::text) || (COALESCE(codes.code_suffix, ''::character varying))::text) AS spec_code,
    a.record_id,
    a.modified,
    a."?column?",
    a.action
   FROM (((a
     LEFT JOIN darwin2.codes ON (((a.record_id = codes.record_id) AND ((codes.referenced_relation)::text = 'specimens'::text) AND ((codes.code_category)::text = 'main'::text))))
     LEFT JOIN darwin2.specimens ON ((a.record_id = specimens.id)))
     LEFT JOIN darwin2.v_collections_full_path_recursive ON ((specimens.collection_ref = v_collections_full_path_recursive.id)));


ALTER TABLE darwin2.v_get_user_tracking_jim_locat OWNER TO darwin2;

