CREATE VIEW darwin2.v_lithology_hierarchy_text AS
 WITH RECURSIVE a AS (
         SELECT lithology.id,
            catalogue_levels.level_name,
            lithology.name,
            jsonb_build_object(catalogue_levels.level_name, lithology.name) AS full_hierarchy_text,
            (('/'::text || ((lithology.id)::character varying)::text) || '/'::text) AS full_hierarchy_id,
            lithology.level_ref,
            catalogue_levels.level_type,
            catalogue_levels.level_sys_name,
            catalogue_levels.optional_level
           FROM (darwin2.lithology
             LEFT JOIN darwin2.catalogue_levels ON ((lithology.level_ref = catalogue_levels.id)))
          WHERE (lithology.parent_ref IS NULL)
        UNION
         SELECT lithology.id,
            catalogue_levels.level_name,
            lithology.name,
            (a_1.full_hierarchy_text || jsonb_build_object(catalogue_levels.level_name, lithology.name)) AS full_hierarchy_text,
            (a_1.full_hierarchy_id || (('/'::text || ((lithology.id)::character varying)::text) || '/'::text)) AS full_hierarchy_id,
            lithology.level_ref,
            catalogue_levels.level_type,
            catalogue_levels.level_sys_name,
            catalogue_levels.optional_level
           FROM ((darwin2.lithology
             JOIN a a_1 ON ((lithology.parent_ref = a_1.id)))
             LEFT JOIN darwin2.catalogue_levels ON ((lithology.level_ref = catalogue_levels.id)))
        )
 SELECT a.id,
    a.level_name,
    a.name,
    a.full_hierarchy_text,
    a.full_hierarchy_id,
    a.level_ref,
    a.level_type,
    a.level_sys_name,
    a.optional_level
   FROM a
  ORDER BY a.level_ref, (a.full_hierarchy_text)::character varying;


