--
-- Name: v_loans_rbins_letter_desc; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_loans_rbins_letter_desc AS
 WITH a AS (
         SELECT loan_items.loan_ref,
            specimens.taxon_name,
            specimens.specimen_count_min,
            specimens.type,
            loans.from_date,
            loans.to_date
           FROM ((darwin2.loans
             LEFT JOIN darwin2.loan_items ON ((loans.id = loan_items.loan_ref)))
             LEFT JOIN darwin2.specimens ON ((loan_items.specimen_ref = specimens.id)))
        ), b AS (
         SELECT a.loan_ref,
            sum(a.specimen_count_min) AS nb_spec,
            a.type,
            a.taxon_name
           FROM a
          WHERE (lower((COALESCE(a.type, 'specimen'::character varying))::text) = 'specimen'::text)
          GROUP BY a.loan_ref, a.type, a.taxon_name
        ), c AS (
         SELECT a.loan_ref,
            sum(a.specimen_count_min) AS nb_spec,
            a.type,
            a.taxon_name
           FROM a
          WHERE (lower((COALESCE(a.type, 'specimen'::character varying))::text) <> 'specimen'::text)
          GROUP BY a.loan_ref, a.type, a.taxon_name
        ), d AS (
         SELECT a.loan_ref,
            ( SELECT sum(a0.specimen_count_min) AS sum
                   FROM a a0
                  WHERE (a0.loan_ref = a.loan_ref)) AS nb_spec_all,
            ( SELECT sum(b0.nb_spec) AS sum
                   FROM b b0
                  WHERE (b0.loan_ref = a.loan_ref)) AS nb_spec_non_type,
            string_agg(DISTINCT ((((b.nb_spec)::character varying)::text || ' '::text) || (b.taxon_name)::text), ', '::text) AS taxon_desc_non_type,
            string_agg(DISTINCT ((((((c.nb_spec)::character varying)::text || ' '::text) || lower((c.type)::text)) || '(s) of '::text) || (c.taxon_name)::text), ', '::text) AS taxon_desc_type,
            a.from_date,
            a.to_date,
            to_char((a.from_date)::timestamp with time zone, 'FMDD FMMonthTH YYYY'::text) AS date_str
           FROM ((a
             LEFT JOIN b ON ((a.loan_ref = b.loan_ref)))
             LEFT JOIN c ON ((a.loan_ref = c.loan_ref)))
          GROUP BY a.loan_ref, a.from_date, a.to_date
        )
 SELECT d.loan_ref,
    d.nb_spec_all,
    d.nb_spec_non_type,
    d.taxon_desc_non_type,
    d.taxon_desc_type,
    d.from_date,
    d.to_date,
    d.date_str,
        CASE
            WHEN ((d.taxon_desc_non_type IS NULL) AND (d.taxon_desc_type IS NULL)) THEN NULL::text
            WHEN ((d.taxon_desc_non_type IS NOT NULL) AND (d.taxon_desc_type IS NULL)) THEN d.taxon_desc_non_type
            WHEN ((d.taxon_desc_non_type IS NULL) AND (d.taxon_desc_type IS NOT NULL)) THEN d.taxon_desc_type
            WHEN ((d.taxon_desc_non_type IS NOT NULL) AND (d.taxon_desc_type IS NOT NULL)) THEN ((d.taxon_desc_non_type || ' and '::text) || d.taxon_desc_type)
            ELSE NULL::text
        END AS desc_str
   FROM d;


ALTER TABLE darwin2.v_loans_rbins_letter_desc OWNER TO darwin2;

--
-- Name: v_migration_compare_gtu_with_tags; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_migration_compare_gtu_with_tags AS
 SELECT v_migration_compare_gtu.specimen_id,
    v_migration_compare_gtu.gtu_id_source,
    v_migration_compare_gtu.gtu_id_dest,
    array_agg(DISTINCT b.tag ORDER BY b.tag) AS source_tags,
    array_agg(DISTINCT c.tag ORDER BY c.tag) AS dest_tags
   FROM ((public.v_migration_compare_gtu
     LEFT JOIN darwin2_rbins_data.tags b ON ((v_migration_compare_gtu.gtu_id_source = b.gtu_ref)))
     LEFT JOIN darwin2_rbins_data.tags c ON ((v_migration_compare_gtu.gtu_id_dest = c.gtu_ref)))
  GROUP BY v_migration_compare_gtu.specimen_id, v_migration_compare_gtu.gtu_id_source, v_migration_compare_gtu.gtu_id_dest;


ALTER TABLE darwin2.v_migration_compare_gtu_with_tags OWNER TO darwin2;

--
-- Name: v_migration_wrong_temporal_information_date; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_migration_wrong_temporal_information_date AS
 SELECT temporal_information.id,
    temporal_information.gtu_ref,
    temporal_information.specimen_ref,
    temporal_information.from_date_mask,
    temporal_information.from_date,
    temporal_information.to_date_mask,
    temporal_information.to_date,
    specimens.gtu_from_date_mask AS specimen_from_date_mask,
    specimens.gtu_from_date AS specimen_from_date,
    specimens.gtu_to_date_mask AS specimen_to_date_mask,
    specimens.gtu_to_date AS specimen_to_date
   FROM (darwin2.temporal_information
     JOIN darwin2_rbins_data.specimens ON ((temporal_information.specimen_ref = specimens.id)))
  WHERE (temporal_information.from_date <> specimens.gtu_from_date);


