--
-- Name: v_mineralogy_hierarchy_text; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_mineralogy_hierarchy_text AS
 WITH RECURSIVE a AS (
         SELECT mineralogy.id,
            catalogue_levels.level_name,
            mineralogy.name,
            jsonb_build_object(catalogue_levels.level_name, mineralogy.name) AS full_hierarchy_text,
            (('/'::text || ((mineralogy.id)::character varying)::text) || '/'::text) AS full_hierarchy_id,
            mineralogy.status,
            mineralogy.local_naming,
            mineralogy.color,
            mineralogy.code,
            mineralogy.classification,
            mineralogy.formule,
            mineralogy.formule_indexed,
            mineralogy.cristal_system,
            mineralogy.level_ref,
            catalogue_levels.level_type,
            catalogue_levels.level_sys_name,
            catalogue_levels.optional_level
           FROM (darwin2.mineralogy
             LEFT JOIN darwin2.catalogue_levels ON ((mineralogy.level_ref = catalogue_levels.id)))
          WHERE (mineralogy.parent_ref IS NULL)
        UNION
         SELECT mineralogy.id,
            catalogue_levels.level_name,
            mineralogy.name,
            (a_1.full_hierarchy_text || jsonb_build_object(catalogue_levels.level_name, mineralogy.name)) AS full_hierarchy_text,
            (a_1.full_hierarchy_id || (('/'::text || ((mineralogy.id)::character varying)::text) || '/'::text)) AS full_hierarchy_id,
            mineralogy.status,
            mineralogy.local_naming,
            mineralogy.color,
            mineralogy.code,
            mineralogy.classification,
            mineralogy.formule,
            mineralogy.formule_indexed,
            mineralogy.cristal_system,
            mineralogy.level_ref,
            catalogue_levels.level_type,
            catalogue_levels.level_sys_name,
            catalogue_levels.optional_level
           FROM ((darwin2.mineralogy
             JOIN a a_1 ON ((mineralogy.parent_ref = a_1.id)))
             LEFT JOIN darwin2.catalogue_levels ON ((mineralogy.level_ref = catalogue_levels.id)))
        )
 SELECT a.id,
    a.level_name,
    a.name,
    a.full_hierarchy_text,
    a.full_hierarchy_id,
    a.status,
    a.local_naming,
    a.color,
    a.code,
    a.classification,
    a.formule,
    a.formule_indexed,
    a.cristal_system,
    a.level_ref,
    a.level_type,
    a.level_sys_name,
    a.optional_level
   FROM a
  ORDER BY a.level_ref, (a.full_hierarchy_text)::character varying;


ALTER TABLE darwin2.v_mineralogy_hierarchy_text OWNER TO darwin2;

