--
-- Name: v_reporting_count_all_spec_category_by_collection_ref_year_ig; Type: MATERIALIZED VIEW; Schema: darwin2; Owner: darwin2
--

CREATE MATERIALIZED VIEW darwin2.v_reporting_count_all_spec_category_by_collection_ref_year_ig AS
 SELECT DISTINCT specimens.collection_path,
    specimens.collection_name,
    specimens.collection_ref,
    specimens.ig_ref,
    specimens.ig_num,
    date_part('year'::text, specimens.specimen_creation_date) AS year,
    specimens.specimen_creation_date,
    specimens.category,
    count(*) AS nb_records,
    sum(specimens.specimen_count_min) AS specimen_count_min,
    sum(specimens.specimen_count_max) AS specimen_count_max,
        CASE
            WHEN (temporal_information.from_date_mask = 0) THEN NULL::timestamp without time zone
            ELSE temporal_information.from_date
        END AS gtu_from_date,
        CASE
            WHEN (temporal_information.to_date_mask = 0) THEN NULL::timestamp without time zone
            ELSE temporal_information.to_date
        END AS gtu_to_date,
        CASE
            WHEN (temporal_information.from_date_mask = 0) THEN NULL::double precision
            ELSE date_part('year'::text, temporal_information.from_date)
        END AS collecting_year
   FROM (darwin2.specimens
     LEFT JOIN darwin2.temporal_information ON ((specimens.id = temporal_information.specimen_ref)))
  GROUP BY specimens.collection_path, specimens.collection_name, specimens.collection_ref, specimens.ig_ref, specimens.ig_num, specimens.specimen_creation_date, (date_part('year'::text, specimens.specimen_creation_date)), specimens.category, temporal_information.from_date_mask, temporal_information.from_date, temporal_information.to_date_mask, temporal_information.to_date
  ORDER BY specimens.category
  WITH NO DATA;


ALTER TABLE darwin2.v_reporting_count_all_spec_category_by_collection_ref_year_ig OWNER TO darwin2;

