           FROM darwin2.specimens
        ), ext_links0 AS (
         SELECT ext_links.referenced_relation,
            ext_links.record_id,
            ext_links.id,
            ext_links.url,
            ext_links.comment,
            ext_links.comment_indexed,
            ext_links.type
           FROM darwin2.ext_links
        ), a AS (
         SELECT a0.id,
            a0.uuid,
            iiif_manifest.url AS urls_iiif_manifest,
            iiif_manifest.type AS image_category_iiif_manifest,
            NULL::character varying AS contributor_iiif_manifest,
            NULL::character varying AS disclaimer_iiif_manifest,
            NULL::character varying AS license_iiif_manifest,
            NULL::integer AS display_order_iiif_manifest,
            iiif_info.url AS urls_iiif_info,
