            "3d_inside".type AS image_category_3d_inside,
            NULL::character varying AS contributor_3d_inside,
            NULL::character varying AS disclaimer_3d_inside,
            NULL::character varying AS license_3d_inside,
            NULL::integer AS display_order_3d_inside,
            html_3d_snippet_general.url AS urls_3d_snippet_general,
            html_3d_snippet_general.type AS image_category_3d_snippet_general,
            NULL::character varying AS contributor_3d_snippet_general,
            NULL::character varying AS disclaimer_3d_snippet_general,
            NULL::character varying AS license_3d_snippet_general,
            NULL::integer AS display_order_3d_snippet_general
           FROM ((((((((((a0
             LEFT JOIN ext_links0 iiif_manifest ON (((a0.id = iiif_manifest.record_id) AND ((iiif_manifest.referenced_relation)::text = 'specimens'::text) AND (iiif_manifest.type = 'iiif'::text))))
             LEFT JOIN ext_links0 iiif_info ON (((a0.id = iiif_info.record_id) AND ((iiif_info.referenced_relation)::text = 'specimens'::text) AND (iiif_info.type = 'iiif_info'::text))))
             LEFT JOIN ext_links0 "2d_stackoptica" ON (((a0.id = "2d_stackoptica".record_id) AND (("2d_stackoptica".referenced_relation)::text = 'specimens'::text) AND ("2d_stackoptica".type = '2d_stackoptica'::text))))
             LEFT JOIN ext_links0 "2d_sphaeroptica" ON (((a0.id = "2d_sphaeroptica".record_id) AND (("2d_sphaeroptica".referenced_relation)::text = 'specimens'::text) AND ("2d_sphaeroptica".type = '2d_sphaeroptica'::text))))
             LEFT JOIN ext_links0 "2d_spectraloptica" ON (((a0.id = "2d_spectraloptica".record_id) AND (("2d_spectraloptica".referenced_relation)::text = 'specimens'::text) AND ("2d_spectraloptica".type = '2d_spectraloptica'::text))))
             LEFT JOIN ext_links0 "2d_polaroptica" ON (((a0.id = "2d_polaroptica".record_id) AND (("2d_polaroptica".referenced_relation)::text = 'specimens'::text) AND ("2d_polaroptica".type = '2d_polaroptica'::text))))
             LEFT JOIN ext_links0 "2d_inside" ON (((a0.id = "2d_inside".record_id) AND (("2d_inside".referenced_relation)::text = 'specimens'::text) AND ("2d_inside".type = '2d_inside'::text))))
             LEFT JOIN ext_links0 "3d_inside" ON (((a0.id = "3d_inside".record_id) AND (("3d_inside".referenced_relation)::text = 'specimens'::text) AND ("3d_inside".type = '3d_inside'::text))))
             LEFT JOIN ext_links0 html_3d_snippet_general ON (((a0.id = html_3d_snippet_general.record_id) AND ((html_3d_snippet_general.referenced_relation)::text = 'specimens'::text) AND (html_3d_snippet_general.type = 'html_3d_snippet_general'::text))))
             LEFT JOIN ext_links0 internal_database ON (((a0.id = internal_database.record_id) AND ((internal_database.referenced_relation)::text = 'specimens'::text) AND (html_3d_snippet_general.type = 'internal_database'::text))))
        )
