--

CREATE VIEW darwin2.v_stijn_taxo_basionym_2024 AS
 WITH a AS (
         SELECT classification_synonymies.referenced_relation,
            classification_synonymies.record_id,
            classification_synonymies.id,
            classification_synonymies.group_id,
            classification_synonymies.group_name,
            classification_synonymies.is_basionym,
            classification_synonymies.order_by,
            classification_synonymies.synonym_record_id,
            classification_synonymies.original_synonym,
            classification_synonymies.import_ref,
            classification_synonymies.syn_date,
            classification_synonymies.syn_date_mask
           FROM darwin2.classification_synonymies
          WHERE classification_synonymies.is_basionym
          ORDER BY classification_synonymies.group_id
        ), b AS (
         SELECT classification_synonymies.referenced_relation,
            classification_synonymies.record_id,
            classification_synonymies.id,
            classification_synonymies.group_id,
            classification_synonymies.group_name,
            classification_synonymies.is_basionym,
            classification_synonymies.order_by,
            classification_synonymies.synonym_record_id,
            classification_synonymies.original_synonym,
            classification_synonymies.import_ref,
            classification_synonymies.syn_date,
            classification_synonymies.syn_date_mask,
            taxonomy.name,
            taxonomy.status,
            darwin2.fct_rmca_sort_taxon_path_alphabetically_not_indexed(taxonomy.path) AS hierarchy
           FROM ((darwin2.classification_synonymies
             JOIN a ON ((classification_synonymies.group_id = a.group_id)))
             LEFT JOIN darwin2.taxonomy ON ((classification_synonymies.record_id = taxonomy.id)))
          WHERE (classification_synonymies.is_basionym = false)
          ORDER BY classification_synonymies.group_id
        ), c AS (
         SELECT a.referenced_relation,
            a.record_id,
            a.id,
            a.group_id,
            a.group_name,
            a.is_basionym,
            a.order_by,
            a.synonym_record_id,
            a.original_synonym,
            a.import_ref,
            a.syn_date,
            a.syn_date_mask,
            taxonomy.name,
            taxonomy.status,
            darwin2.fct_rmca_sort_taxon_path_alphabetically_not_indexed(taxonomy.path) AS hierarchy
           FROM (a
             LEFT JOIN darwin2.taxonomy ON ((a.record_id = taxonomy.id)))
        )
 SELECT c.record_id,
    c.group_id,
    c.name AS name_of_basionym,
    c.hierarchy AS hierarchy_for_basionym,
    c.status AS status_for_basionym,
    c.group_name AS type_synonym_for_basionym,
    c.is_basionym,
    c.original_synonym AS is_also_original_synonym,
    string_agg((((((((b.name)::text || ' '::text) || (b.status)::text) || ' '::text) || (b.group_name)::text) || ' , original_synonym: '::text) || b.original_synonym), '; '::text) AS name_related,
    string_agg((b.hierarchy)::text, '; '::text) AS hierarchy_related,
    (c.record_id || array_agg(b.record_id)) AS names_id
   FROM (c
     LEFT JOIN b ON ((c.group_id = b.group_id)))
  GROUP BY c.record_id, c.group_id, c.name, c.hierarchy, c.status, c.group_name, c.is_basionym, c.original_synonym
  ORDER BY c.name;


