    ( SELECT users.formated_name
           FROM darwin2.users
          WHERE (users.id = users_tracking.user_ref)) AS encoder
   FROM (((darwin2.specimens
     JOIN darwin2.v_collections_full_path_recursive ON ((specimens.collection_ref = v_collections_full_path_recursive.id)))
     JOIN darwin2.codes ON ((((codes.referenced_relation)::text = 'specimens'::text) AND ((codes.code_category)::text = 'main'::text) AND (specimens.id = codes.record_id))))
     LEFT JOIN darwin2.users_tracking ON (((specimens.id = users_tracking.record_id) AND ((users_tracking.referenced_relation)::text = 'specimens'::text) AND ((users_tracking.action)::text = 'insert'::text))))
  WHERE (specimens.taxon_ref IN ( SELECT unnest(v_stijn_taxo_basionym_2024.names_id) AS unnest
           FROM darwin2.v_stijn_taxo_basionym_2024));


