           FROM (a
             JOIN darwin2.v_taxonomy_path_recurs_text ON ((a.record_id = v_taxonomy_path_recurs_text.id)))
        )
 SELECT b.group_id,
    (array_agg(b.name ORDER BY b.record_id))[1] AS oldest_name_in_db,
