--
-- Name: v_taxonomy_remove_authors_for_check; Type: VIEW; Schema: darwin2; Owner: darwin2
--

CREATE VIEW darwin2.v_taxonomy_remove_authors_for_check AS
 WITH a AS (
         SELECT
                CASE
                    WHEN (taxonomy.level_ref < 48) THEN split_part((taxonomy.name)::text, ' '::text, 1)
                    ELSE btrim(regexp_replace(regexp_replace(regexp_replace(regexp_replace((taxonomy.name)::text, '\([^\)]*\)'::text, ''::text, 'g'::text), '[0-9]|,| ssp.| var.| ssp | var |\.|&'::text, ''::text, 'g'::text), '\s[A-Z]\w*'::text, ''::text, 'g'::text), '\s+'::text, ' '::text, 'g'::text))
                END AS no_parenthesis,
            taxonomy.name,
            taxonomy.name_indexed,
            taxonomy.level_ref,
            taxonomy.status,
            taxonomy.local_naming,
            taxonomy.color,
            taxonomy.path,
            taxonomy.parent_ref,
            taxonomy.metadata_ref,
            taxonomy.id,
            taxonomy.extinct,
            taxonomy.taxonomy_creation_date,
            taxonomy.import_ref,
            taxonomy.sensitive_info_withheld,
            taxonomy.is_reference_taxonomy,
            taxonomy.cites,
            taxonomy.nomen_nodum
           FROM darwin2.taxonomy
        )
 SELECT
        CASE
            WHEN (a.level_ref < 48) THEN a.no_parenthesis
            WHEN (a.level_ref = 48) THEN ((split_part(a.no_parenthesis, ' '::text, 1) || ' '::text) || split_part(a.no_parenthesis, ' '::text, 2))
            WHEN (a.level_ref > 48) THEN ((((split_part(a.no_parenthesis, ' '::text, 1) || ' '::text) || split_part(a.no_parenthesis, ' '::text, 2)) || ' '::text) || split_part(a.no_parenthesis, ' '::text, 3))
            ELSE NULL::text
        END AS name_no_author,
    a.no_parenthesis,
    a.name,
    a.name_indexed,
    a.level_ref,
    a.status,
    a.local_naming,
    a.color,
    a.path,
    a.parent_ref,
    a.metadata_ref,
    a.id,
    a.extinct,
    a.taxonomy_creation_date,
    a.import_ref,
    a.sensitive_info_withheld,
    a.is_reference_taxonomy,
    a.cites,
    a.nomen_nodum
   FROM a;


ALTER TABLE darwin2.v_taxonomy_remove_authors_for_check OWNER TO darwin2;

