    col_api.count_col,
    col_api.current_col,
    col_api.col_usage_key,
    col_api.col_status,
    col_api.col_rank,
    col_api.col_scientific_name,
    col_api.col_authorship,
    col_api.col_link,
    col_api.col_hierarchy_names,
    col_api.col_hierarchy_ranks,
    (replace(replace((col_api.json_col)::text, '\r'::text, ' '::text), '\n'::text, ' '::text))::character varying AS json_col,
        CASE
            WHEN (col_api.col_scientific_name IS NULL) THEN 'not_found'::text
            WHEN ("position"((v_taxonomy_remove_authors_for_check.name)::text, (('('::text || (col_api.col_authorship)::text) || ')'::text)) > 0) THEN 'same_author_different_parenthesis'::text
            WHEN ("position"((v_taxonomy_remove_authors_for_check.name)::text, (col_api.col_authorship)::text) > 0) THEN 'same_author'::text
            ELSE 'other_author'::text
        END AS col_match_type
   FROM ((darwin2.v_taxonomy_remove_authors_for_check
     JOIN darwin2.catalogue_levels ON ((v_taxonomy_remove_authors_for_check.level_ref = catalogue_levels.id)))
     LEFT JOIN LATERAL darwin2.fct_rmca_taxon_to_catalogolife_api_rank((v_taxonomy_remove_authors_for_check.name_no_author)::character varying, catalogue_levels.level_name) col_api(url_col, count_col, current_col, col_usage_key, col_status, col_rank, col_scientific_name, col_authorship, col_link, col_hierarchy_names, col_hierarchy_ranks, json_col) ON ((1 = 1)));


