--
-- Name: v_georef_virunga; Type: VIEW; Schema: wfs; Owner: darwin2
--

CREATE VIEW wfs.v_georef_virunga AS
 WITH a AS (
         SELECT "CongoRDC_parcs_rgc_2019".gid,
            "CongoRDC_parcs_rgc_2019".geom,
            "CongoRDC_parcs_rgc_2019".sce_sem,
            "CongoRDC_parcs_rgc_2019".sce_geo,
            "CongoRDC_parcs_rgc_2019".date,
            "CongoRDC_parcs_rgc_2019".origine,
            "CongoRDC_parcs_rgc_2019".name,
            "CongoRDC_parcs_rgc_2019".reglement
           FROM wfs."CongoRDC_parcs_rgc_2019"
          WHERE (("CongoRDC_parcs_rgc_2019".name)::text ~~* '%virunga%'::text)
        ), b AS (
         SELECT gtu.id,
            gtu.code,
            gtu.gtu_from_date_mask,
            gtu.gtu_from_date,
            gtu.gtu_to_date_mask,
            gtu.gtu_to_date,
            gtu.tag_values_indexed,
            gtu.latitude,
            gtu.longitude,
            gtu.lat_long_accuracy,
            gtu.location,
            gtu.elevation,
            gtu.elevation_accuracy,
            gtu.latitude_dms_degree,
            gtu.latitude_dms_minutes,
            gtu.latitude_dms_seconds,
            gtu.latitude_dms_direction,
            gtu.longitude_dms_degree,
            gtu.longitude_dms_minutes,
            gtu.longitude_dms_seconds,
            gtu.longitude_dms_direction,
            gtu.latitude_utm,
            gtu.longitude_utm,
            gtu.utm_zone,
            gtu.coordinates_source,
            gtu.gtu_creation_date,
            gtu.import_ref,
            gtu.iso3166,
            gtu.iso3166_subdivision,
            gtu.nagoya,
            gtu.collection_ref,
            gtu.collector_refs,
            gtu.expedition_refs,
            gtu.geom,
            gtu.expedition_ref
           FROM darwin2.gtu,
            a
          WHERE public.st_intersects(a.geom, public.st_setsrid(public.st_point(gtu.location[1], gtu.location[0]), 4326))
        ), c AS (
         SELECT tags.gtu_ref,
            string_agg((tags.tag)::text, '; '::text ORDER BY tags.gtu_ref) AS locality
           FROM (darwin2.tags
             JOIN b b_1 ON ((tags.gtu_ref = b_1.id)))
          GROUP BY tags.gtu_ref
        ), d AS (
         SELECT specimens.gtu_ref,
            specimens.gtu_from_date,
            specimens.gtu_from_date_mask,
            specimens.spec_coll_ids,
            v_rmca_collections_path_as_text.collection_path_text,
            count(specimens.id) AS nb_records
           FROM ((c c_1
             JOIN darwin2.specimens ON ((c_1.gtu_ref = specimens.gtu_ref)))
             JOIN darwin2.v_rmca_collections_path_as_text ON ((specimens.collection_ref = v_rmca_collections_path_as_text.id)))
          WHERE (specimens.gtu_from_date > '0001-01-01 00:00:00'::timestamp without time zone)
          GROUP BY specimens.gtu_ref, specimens.gtu_from_date, specimens.gtu_from_date_mask, specimens.spec_coll_ids, v_rmca_collections_path_as_text.collection_path_text
         HAVING (specimens.gtu_from_date = min(specimens.gtu_from_date))
        ), e1 AS (
         SELECT d_1.gtu_ref,
            unnest(d_1.spec_coll_ids) AS coll_id
           FROM d d_1
        ), e2 AS (
         SELECT e1.gtu_ref,
            string_agg((people.formated_name)::text, '; '::text) AS formated_name
           FROM (e1
             JOIN darwin2.people ON ((e1.coll_id = people.id)))
          GROUP BY e1.gtu_ref
        )
 SELECT (c.locality)::character varying AS locality,
    darwin2.fct_mask_date(d.gtu_from_date, d.gtu_from_date_mask) AS date,
    e2.formated_name AS collector,
    b.id,
    b.code,
    b.gtu_from_date_mask,
    b.gtu_from_date,
