--
-- Name: wfs_translation_geom; Type: VIEW; Schema: wfs; Owner: darwin2
--

CREATE VIEW wfs.wfs_translation_geom AS
 SELECT a.gid,
    a.source_table,
    a.wikidataid,
    a.name,
    a.translated_name,
    darwin2.fulltoindex(a.translated_name, true) AS translated_name_indexed,
    a.language,
