--
-- Name: mv_doctrine_temporal_information_gtu_group_tags; Type: MATERIALIZED VIEW; Schema: darwin2; Owner: darwin2
--

CREATE MATERIALIZED VIEW darwin2.mv_doctrine_temporal_information_gtu_group_tags AS
 SELECT DISTINCT gtu.id,
    gtu.code,
    gtu.gtu_from_date_mask,
    gtu.gtu_from_date,
    gtu.gtu_to_date_mask,
    gtu.gtu_to_date,
    gtu.tag_values_indexed,
    gtu.latitude,
    gtu.longitude,
    gtu.lat_long_accuracy,
    gtu.elevation,
    gtu.elevation_accuracy,
    (gtu.location)::character varying AS location,
    gtu.gtu_creation_date,
    gtu.import_ref,
    gtu.collector_refs,
    gtu.expedition_refs,
    gtu.collection_ref,
    gtu.latitude_dms_degree,
    gtu.latitude_dms_minutes,
    gtu.latitude_dms_seconds,
    gtu.latitude_dms_direction,
    gtu.longitude_dms_degree,
    gtu.longitude_dms_minutes,
    gtu.longitude_dms_seconds,
    gtu.longitude_dms_direction,
    gtu.latitude_utm,
    gtu.longitude_utm,
    gtu.utm_zone,
    gtu.coordinates_source,
    array_agg(temporal_information.from_date_mask) AS array_from_date_mask,
    array_agg(temporal_information.from_date) AS array_from_date,
    array_agg(temporal_information.to_date_mask) AS array_to_date_mask,
    array_agg(temporal_information.to_date) AS array_to_date,
    string_agg(DISTINCT btrim((((COALESCE(c.notion_concerned, ''::character varying))::text || ' : '::text) || COALESCE(c.comment))), '|'::text ORDER BY (btrim((((COALESCE(c.notion_concerned, ''::character varying))::text || ' : '::text) || COALESCE(c.comment)))), '|'::text) AS comments,
    string_agg(DISTINCT btrim((((COALESCE((((properties.property_type)::text || COALESCE((' - '::text || (properties.applies_to)::text), ''::text)) || ' : '::text), ''::text) || (COALESCE(properties.lower_value, ''::character varying))::text) || COALESCE(('-'::text || (properties.upper_value)::text), ''::text)) || COALESCE((' '::text || (properties.property_unit)::text), ''::text))), '|'::text ORDER BY (btrim((((COALESCE((((properties.property_type)::text || COALESCE((' - '::text || (properties.applies_to)::text), ''::text)) || ' : '::text), ''::text) || (COALESCE(properties.lower_value, ''::character varying))::text) || COALESCE(('-'::text || (properties.upper_value)::text), ''::text)) || COALESCE((' '::text || (properties.property_unit)::text), ''::text)))), '|'::text) AS properties,
    tags.tag,
    tags.tag_indexed,
    gtu.expedition_ref,
    gtu_to_country.country_ref
   FROM (((((darwin2.gtu
     LEFT JOIN darwin2.temporal_information ON ((gtu.id = temporal_information.gtu_ref)))
     LEFT JOIN darwin2.comments c ON ((((c.referenced_relation)::text = 'gtu'::text) AND (gtu.id = c.record_id))))
     LEFT JOIN darwin2.properties ON ((((properties.referenced_relation)::text = 'gtu'::text) AND (gtu.id = properties.record_id))))
     LEFT JOIN darwin2.tags ON ((gtu.id = tags.gtu_ref)))
     LEFT JOIN darwin2.gtu_to_country ON ((gtu.id = gtu_to_country.gtu_ref)))
  GROUP BY gtu.id, gtu.code, gtu.gtu_from_date_mask, gtu.gtu_from_date, gtu.gtu_to_date_mask, gtu.gtu_to_date, gtu.tag_values_indexed, gtu.latitude, gtu.longitude, gtu.lat_long_accuracy, gtu.elevation, gtu.elevation_accuracy, (gtu.location)::character varying, gtu.gtu_creation_date, gtu.import_ref, gtu.collector_refs, gtu.expedition_refs, gtu.collection_ref, gtu.latitude_dms_degree, gtu.latitude_dms_minutes, gtu.latitude_dms_seconds, gtu.latitude_dms_direction, gtu.longitude_dms_degree, gtu.longitude_dms_minutes, gtu.longitude_dms_seconds, gtu.longitude_dms_direction, gtu.latitude_utm, gtu.longitude_utm, gtu.utm_zone, gtu.coordinates_source, tags.tag, tags.tag_indexed, temporal_information.gtu_ref, c.record_id, properties.record_id, tags.gtu_ref, gtu_to_country.gtu_ref, gtu_to_country.country_ref
  WITH NO DATA;


ALTER TABLE darwin2.mv_doctrine_temporal_information_gtu_group_tags OWNER TO darwin2;

