--
-- Name: mv_eml; Type: MATERIALIZED VIEW; Schema: ipt; Owner: postgres
--

CREATE MATERIALIZED VIEW ipt.mv_eml AS
 SELECT ((((((('The '::text || c.title_en) || ' contains '::text) || c.total) || ' digitised specimens of '::text) || c.nb_species) || ' taxa. The following classes are included: '::text) || c.class_taxonomic_coverage) AS abstract,
    c.total AS nb_specimens,
    c.nb_species,
    NULL::text AS ig_num,
    c.ranks,
    NULL::text AS existing_code,
    c.id,
    c.name,
    c.code,
    c.title_en,
    c.title_nl,
    c.title_fr,
    c.profile,
    c.path,
    c.geographic_coverage,
    c.min_lon,
    c.max_lon,
    c.min_lat,
    c.max_lat,
    c.start_date,
    c.end_date,
    ('natural history collection, RBINS, DaRWIN, '::text || (c.name)::text) AS keywords,
    'Royal Belgian Institute for Natural Sciences'::text AS institute_name,
    'Department of Scientific Heritage Service'::text AS institute_dept_abbrev,
    (((curator.given_name)::text || ' '::text) || (curator.family_name)::text) AS boss,
    uc1.entry AS boss_email,
    'curator'::text AS boss_role,
    (((staff.given_name)::text || ' '::text) || (staff.family_name)::text) AS subboss,
    uc2.entry AS subboss_email,
    'Collection manager'::text AS subboss_role,
    c.class_taxonomic_coverage,
    c.order_taxonomic_coverage
   FROM ((((( SELECT c_1.id,
            c_1.name,
            c_1.name_indexed AS code,
            c_1.title_en,
            c_1.title_nl,
            c_1.title_fr,
            c_1.profile,
            c_1.path,
            string_agg(DISTINCT mv_darwin_ipt_rbins_old.country, ', '::text) AS geographic_coverage,
            min(mv_darwin_ipt_rbins_old.decimal_longitude) AS min_lon,
            max(mv_darwin_ipt_rbins_old.decimal_longitude) AS max_lon,
            min(mv_darwin_ipt_rbins_old.decimal_latitude) AS min_lat,
            max(mv_darwin_ipt_rbins_old.decimal_latitude) AS max_lat,
            min(mv_darwin_ipt_rbins_old.event_date) AS start_date,
            max(mv_darwin_ipt_rbins_old.event_date) AS end_date,
            c_1.main_manager_ref,
            c_1.staff_ref,
            count(*) AS total,
            count(DISTINCT mv_darwin_ipt_rbins_old.scientific_name) AS nb_species,
            string_agg(DISTINCT (mv_darwin_ipt_rbins_old.taxon_rank)::text, ', '::text) AS ranks,
            string_agg(DISTINCT mv_darwin_ipt_rbins_old.class, ', '::text) AS class_taxonomic_coverage,
            string_agg(DISTINCT mv_darwin_ipt_rbins_old.ordo, ', '::text) AS order_taxonomic_coverage
           FROM (ipt.mv_darwin_ipt_rbins_old
             LEFT JOIN darwin2.collections c_1 ON ((mv_darwin_ipt_rbins_old.ndwc_collection_path ~~ (('%/'::text || c_1.id) || '/%'::text))))
          WHERE ((c_1.name_indexed)::text = 'aves'::text)
          GROUP BY c_1.id, c_1.name, c_1.name_indexed, c_1.title_en, c_1.title_nl, c_1.title_fr, c_1.profile, c_1.path
        UNION ALL
         SELECT c_1.id,
            c_1.name,
            c_1.name_indexed AS code,
            c_1.title_en,
            c_1.title_nl,
            c_1.title_fr,
            c_1.profile,
            c_1.path,
            string_agg(DISTINCT mv_darwin_ipt_rbins_old.country, ', '::text) AS geographic_coverage,
            min(mv_darwin_ipt_rbins_old.decimal_longitude) AS min_lon,
            max(mv_darwin_ipt_rbins_old.decimal_longitude) AS max_lon,
            min(mv_darwin_ipt_rbins_old.decimal_latitude) AS min_lat,
            max(mv_darwin_ipt_rbins_old.decimal_latitude) AS max_lat,
            min(mv_darwin_ipt_rbins_old.event_date) AS start_date,
            max(mv_darwin_ipt_rbins_old.event_date) AS end_date,
            c_1.main_manager_ref,
            c_1.staff_ref,
            count(*) AS total,
            count(DISTINCT mv_darwin_ipt_rbins_old.scientific_name) AS nb_species,
            string_agg(DISTINCT (mv_darwin_ipt_rbins_old.taxon_rank)::text, ', '::text) AS ranks,
            string_agg(DISTINCT mv_darwin_ipt_rbins_old.class, ', '::text) AS class_taxonomic_coverage,
            string_agg(DISTINCT mv_darwin_ipt_rbins_old.ordo, ', '::text) AS order_taxonomic_coverage
           FROM (ipt.mv_darwin_ipt_rbins_old
             LEFT JOIN darwin2.collections c_1 ON ((mv_darwin_ipt_rbins_old.ndwc_collection_path ~~ (('%/'::text || c_1.id) || '/%'::text))))
          WHERE ((c_1.name_indexed)::text = 'belgianmarineinvertebrates'::text)
          GROUP BY c_1.id, c_1.name, c_1.name_indexed, c_1.title_en, c_1.title_nl, c_1.title_fr, c_1.profile, c_1.path
        UNION ALL
